// Helpers de la registry
function _countryEntry(cc){ return COUNTRIES_REG[cc] || null; }
// True si l'espece est un X (Echappe) trop anecdotique pour meriter une fiche dans ce
// pays : presente sur moins de la moitie de l'annee. Ecarte les oiseaux de cage echappes
// une fois (Ara bleu, Cacatoes blanc, Inseparable masque, Perroquet jaco... 2 a 5 mois)
// et garde ceux qu'on croise reellement en parc ou sur un plan d'eau (Canard musque,
// Paon bleu, Perruche alexandre, Calopsitte... 6 a 12 mois).
//
// Attention aux criteres bases sur la VALEUR des frequences : 0.0015 (0.15%) est la
// valeur PLANCHER d'eBird, posee des qu'une espece a ete vue au moins une fois dans le
// mois, pas une frequence mesuree. Sur les 45 X de France qui passaient le filtre
// precedent, 40 ne depassent ce plancher aucun mois de l'annee : un seuil sur la moyenne
// ou sur le pic mesure donc ce plancher et non la presence reelle. Seul le nombre de mois
// distincts est exploitable.
//
// N'agit que sur les X, garde les N/P meme rares.
const _MOIS_MIN_X_VISIBLE = 6;
function _isIsolatedXExotic(sci, cc){
  const k = (sci||'').toLowerCase();
  const catByEbird = (EXOTIQUES_EBIRD_PAR_PAYS[cc] && EXOTIQUES_EBIRD_PAR_PAYS[cc][k]) || '';
  if(catByEbird !== 'X') return false;
  // Exception : si l'espece a une population native forte dans une region (ex : Oie
  // empereur en Alaska pour US), le tag X national est aberrant - on garde l'espece
  // visible, elle sera traitee comme native via l'override dans exoticCategoryInCountry.
  if(_hasNativeRegionalPresence(k, cc)) return false;
  const e = _countryEntry(cc); if(!e) return false;
  const monArr = e.monthly() && e.monthly()[k];
  // Aucune serie mensuelle alors que l'espece a un tier de rarete : sa frequence est trop
  // basse pour que le build ait pu agreger douze mois. C'est donc une observation isolee,
  // et la fiche le dit deja — son graphique affiche "Pas de donnees eBird, echappe
  // cage/voliere". On ecarte, pour que la Birdydex soit d'accord avec la fiche.
  // Concerne 5 especes en France (Faucon laggar, Bulbul orphee, Perriche veuve, Sarcelle a
  // collier, Dendrocygne a ventre noir), aucune dans les 14 autres pays.
  if(!Array.isArray(monArr) || !monArr.length) return true;
  return monArr.filter(v => v > 0).length < _MOIS_MIN_X_VISIBLE;
}
function _countryHasSpecies(cc, sci){
  const e = _countryEntry(cc); if(!e) return false;
  const k = (sci||'').toLowerCase();
  const stEntry = e.st()[k];
  // Espece consideree presente si :
  //   - bar chart tier > 0
  //   - OU S&T avec un composite tier ET une abondance reelle dans le pays
  //
  // Cette seconde condition testait seulement `stEntry.t > 0`, pour admettre les vagrants
  // que Cornell modelise avec w=[0,0,...] mais t=10. Or ce t=10 est le plancher de la
  // fonction de tier applique a une abondance nulle, pas une mesure : il admettait
  // 50 especes au catalogue francais qui n'y ont rien a faire (Vautour oricou, Damier du
  // Cap, Petrel geant...), toutes avec abondance ET valeurs hebdo strictement nulles.
  // Meme garde que pour la rarete, cf. _stUtilisable.
  const hasBar = !!e.barTier()[k];
  // La presence hebdomadaire S&T a ete retiree le 2026-09-28. Elle ne decidait plus rien :
  // mesure sur les 456 especes de la table, 399 entrent au catalogue par leur bar chart eBird,
  // ZERO par la seule presence hebdomadaire, zero par le seul tier. Les 52 valeurs de Cornell
  // pesaient 24,6 Ko servis pour cette unique question oui/non, et l indicateur qui les avait
  // remplacees 145 octets de plus. La table ne porte donc plus ni w ni p - voir
  // tools/build/compacte-abondance-st.mjs.
  const hasSTTier = _stUtilisable(stEntry);
  if(!hasBar && !hasSTTier) return false;
  // Filtre X isolés : les échappés (X) qui n'apparaissent que sur ≤ 3 mois
  // et avec un max < 0.01% sont considérés comme "observations ponctuelles" et non
  // comme espèce présente. Empêche les Diamant de Gould et autres échappés de compagnie
  // de polluer la birdydex pays. N'affecte que les X, pas les N/P (populations établies).
  if(_isIsolatedXExotic(sci, cc)) return false;
  return true;
}

