// Met a jour le label + drapeau d'un bouton pays (data-cc + spans .cp-btn-flag/label).
// Utilise flagImg (<img flagcdn>) pour rendu cross-platform (Windows n'affiche pas les emoji).
// GLOBAL COUNTRY : filtre pays applique a tout le site (Birdydex, Cette semaine, Carte).
// La fiche espece garde son picker local pour comparer avec le pays global.
// Persiste dans localStorage sous 'mb-global-country'.
let _globalCountry = 'FR';
try{ _globalCountry = localStorage.getItem('mb-global-country') || 'FR'; }catch(_){}
function _setGlobalCountry(cc){
  if(!cc || cc === _globalCountry) return;
  _globalCountry = cc;
  try{ localStorage.setItem('mb-global-country', cc); }catch(_){}
  // Sync tous les states de pages
  if(typeof _pkdxFilters === 'object'){
    _pkdxFilters.country = cc;
    try{ localStorage.setItem('mb-pkdx-filters', JSON.stringify(_pkdxFilters)); }catch(_){}
    if(typeof _pkdxAllSorted !== 'undefined') _pkdxAllSorted = null;
    if(typeof _pkdxNumById !== 'undefined') _pkdxNumById = null;
    if(typeof _pkdxLastRowsHash !== 'undefined') _pkdxLastRowsHash = null;
  }
  if(typeof ebFilter === 'object'){
    ebFilter.country = cc;
    ebFilter.region = cc;
    ebFilter.dept = '';
    // Sync le select mapEbCountry (cache mais actif pour compat)
    const mec = document.getElementById('mapEbCountry');
    if(mec) mec.value = cc;
  }
  // Sync le bouton global visuel
  const gb = document.getElementById('globalCountryBtn');
  if(gb) _syncCountryButton(gb, cc);
  // Re-render la vue active
  try{
    const activeView = [...document.querySelectorAll('.tab.on')][0]?.dataset?.view;
    if(activeView === 'pokedex' && typeof _pkdxRender === 'function') _pkdxRender();
    else if(activeView === 'map' && typeof renderMap === 'function') renderMap();
  }catch(e){ console.warn('sync view after country change :', e.message); }
}
function _syncCountryButton(btn, cc){
  if(!btn) return;
  const reg = COUNTRIES_REG[cc];
  const name = (reg && reg.name) || cc;
  btn.dataset.cc = cc;
  const fEl = btn.querySelector('.cp-btn-flag');
  const lEl = btn.querySelector('.cp-btn-label');
  if(fEl) fEl.innerHTML = flagImg(cc);
  if(lEl) lEl.textContent = name;
}
// Ouvre le modal, retourne une promesse resolue avec le code pays choisi (ou null si ferme).
// availableFilter : optionnel, fonction (cc) => bool pour disable certains pays.
// Selecteur geographique plein ecran. Avec `opts.zones`, il gagne un second onglet et
// devient le selecteur unique : pays et zone sont le meme choix - l'endroit ou on lit la
// rarete - et ils vivaient dans deux objets differents, un modal plein ecran pour le pays
// et un panneau deroulant pour la zone. Changer de pays puis de departement demandait de
// fermer l'un pour ouvrir l'autre.
//   opts.zones(cc)   -> le HTML des lignes .reg-picker-item du pays cc
//   opts.onPays(cc)  -> applique le changement de pays et attend ses donnees
//   opts.motZone     -> 'Départements' / 'Régions', chaine ou fonction de cc
//   opts.onglet      -> 'zones' pour ouvrir directement sur les zones
// Resolution : sans zones, le code pays comme avant ; avec zones, { type:'zone', code }
// quand une zone est choisie, null a la fermeture - le changement de pays, lui, a deja
// ete applique par opts.onPays.
function _openCountryPicker(currentCode, opts = {}){
  return new Promise((resolve) => {
    const avecZones = typeof opts.zones === 'function';
    let ccCourant = currentCode;
    let onglet = (opts.onglet === 'zones' && avecZones) ? 'zones' : 'pays';
    const motZone = (cc) => typeof opts.motZone === 'function' ? opts.motZone(cc)
      : (opts.motZone || 'Régions');
    // Mois choisi sur la carte de la fiche. Le selecteur s'aligne dessus : son titre l'annonce,
    // et ses deux listes donnent la valeur de ce mois au lieu de la moyenne annuelle.
    const _mmSel = window._smRarityMapMonth;
    const moisLu = (typeof _mmSel === 'number' && _mmSel >= 0 && _mmSel <= 11) ? _mmSel : null;
    const _ZONE_SINGULIER = {
      'Départements': 'un département', 'Régions': 'une région', 'Provinces': 'une province',
      'Cantons': 'un canton', 'États': 'un état', 'Comtés': 'un comté',
    };
    const availableCodes = opts.availableCodes || Object.keys(COUNTRIES_REG);
    const allCodes = availableCodes.filter(cc => COUNTRIES_REG[cc]);
    // Si opts.sci est passe (appel depuis fiche espece), on trie par abondance pour
    // cette espece et on affiche un indicateur (max weekly S&T ou % pic monthly).
    const focusSci = opts.sci ? opts.sci.toLowerCase() : null;
    // Uniquement le bar chart mensuel (% de listes). Le repli S&T qui existait ici
    // renvoyait un score en ind/h, trie dans la meme liste que des pourcentages : un pays
    // note 0.015 ind/h se retrouvait classe comme un pays a 1,5 % de listes. Il ne se
    // declenchait que pour 6 especes francaises, toutes pourvues d'un tier bar chart et
    // seulement privees de tableau mensuel. Elles scorent desormais 0 comme les 40 autres
    // especes dans le meme cas, ce qui est au moins coherent. Meme choix que le panneau
    // regional, qui ne lit plus que le bar chart lui aussi.
    // `score` sert a dire si l'espece est absente du pays : c'est le PIC, car une espece
    // vue un seul mois n'est pas absente. `aff` est la valeur reellement AFFICHEE sur la
    // ligne - moyenne annuelle ponderee, ou le mois choisi sur la carte. Les deux sont
    // distinctes : au mois de janvier un migrateur estival affiche 0 sans etre absent.
    const scoreCountryForSpecies = (cc) => {
      const reg = COUNTRIES_REG[cc];
      const monArr = reg.monthly()[focusSci];
      if(!Array.isArray(monArr)) return { score: 0, aff: 0, isSt: false };
      const pic = Math.max(...monArr);
      const aff = (moisLu == null) ? _valeurAnnuelleZone(monArr, cc) : (monArr[moisLu] || 0);
      return { score: pic > 0 ? pic : 0, aff: aff || 0, isSt: false };
    };
    // Meme format que la liste des zones, au chiffre pres : les deux listes se lisent
    // l'une apres l'autre dans le meme selecteur.
    const fmtPct = v => { if(!(v>0)) return '-'; const p = v*100;
      if(p >= 10) return Math.round(p)+_PCT;
      if(p >= 0.1) return _fr(p.toFixed(1))+_PCT;
      return _fr(Number(p.toPrecision(1)))+_PCT; };
    // Grouper par continent (avec optionnel score espece)
    const grouped = {};
    for(const cc of allCodes){
      const cont = CONTINENT_BY_CC[cc] || 'Autres';
      if(!grouped[cont]) grouped[cont] = [];
      const scored = focusSci ? scoreCountryForSpecies(cc) : null;
      grouped[cont].push({ cc, score: scored ? scored.score : null,
                           aff: scored ? scored.aff : 0, isSt: scored ? scored.isSt : false });
    }
    // Si focusSci : les pays ou l'espece est absente vont a la fin, les autres se classent
    // par le POURCENTAGE AFFICHE, decroissant - comme la liste des zones juste a cote.
    //
    // Le tri portait d'abord sur le palier seul : une espece repandue met une vingtaine de
    // pays dans le palier 1, qui retombaient alors dans l'ordre de declaration de
    // COUNTRIES_REG, et la colonne se lisait 27, 29, 26, 41, 42, 25 %. Puis sur le palier
    // puis le pourcentage, ce qui ne reglait rien : un pays de palier 2 a 34 % passait
    // derriere tous les paliers 1, jusqu'a ceux a 5 %.
    //
    // Le pourcentage peut trancher seul parce qu'il est homogene : il vient TOUJOURS du bar
    // chart eBird (REAL_FREQ_MONTHLY_XX), jamais de Status & Trends. S&T n'entre que dans le
    // calcul du palier, et seuls six pays en portent encore une table. Le palier ne sert donc
    // plus qu'a departager a pourcentage egal - mesure faite sur six especes repandues :
    // classer par pourcentage seul ne desordonne la colonne des paliers que dans 2 % des
    // couples voisins, tous chez ces six pays.
    if(focusSci){
      const absentOf = (x) => x.score === 0 ? 1 : 0;
      for(const cont in grouped){
        grouped[cont].sort((a, b) => (absentOf(a) - absentOf(b)) || (b.aff - a.aff)
          || (rarityForCountry(focusSci, a.cc) - rarityForCountry(focusSci, b.cc)));
      }
    } else {
      // Sans espece ciblee - ouverture depuis le birdydex - la liste ne sert plus a
      // comparer mais a TROUVER un pays. On la classe donc par nom, ce que le champ de
      // recherche juste au-dessus laisse attendre.
      //
      // Elle suivait jusqu'ici l'ordre dans lequel les pays ont ete ajoutes au code, qui
      // ne dit rien a personne : le Montenegro tenait la deuxieme ligne parce qu'il fut
      // le deuxieme pays du projet. La France garde la premiere, elle, parce qu'elle est
      // le pays par defaut de l'application.
      for(const cont in grouped){
        grouped[cont].sort((a, b) =>
          (a.cc === 'FR' ? -1 : b.cc === 'FR' ? 1 : 0)
          || (COUNTRIES_REG[a.cc].name || a.cc).localeCompare(COUNTRIES_REG[b.cc].name || b.cc, 'fr'));
      }
    }
    const backdrop = document.createElement('div');
    backdrop.className = 'cp-modal-backdrop';
    backdrop.innerHTML = `
      <div class="cp-modal-inner">
        <div class="cp-modal-title">
          <span>${avecZones ? 'Rareté' + (moisLu == null ? '' : ' · ' + _MOIS_COURTS[moisLu]) : 'Choisir un pays'}</span>
          <button type="button" class="cp-modal-close" aria-label="Fermer">×</button>
        </div>
        ${avecZones ? `<div class="cp-tabs">
          <button type="button" class="cp-tab" data-onglet="pays">Pays</button>
          <button type="button" class="cp-tab" data-onglet="zones">${esc(motZone(ccCourant))}</button>
        </div>` : ''}
        <input type="search" name="cp-search" aria-label="Rechercher par nom francais" class="cp-search" placeholder="Rechercher un pays…" autofocus>
        <div class="cp-list"></div>
      </div>`;
    const listEl = backdrop.querySelector('.cp-list');
    // Largeur de la case des lettres : celle du pays qui en porte le plus, sur TOUTE la
    // liste et non sur ce qui est affiche. Elle doit valoir pareil dans les deux onglets,
    // sinon les colonnes sautent quand on passe de l'un a l'autre ; et elle ne doit pas
    // suivre le filtre, sinon taper trois lettres deplace la colonne des chiffres.
    {
      let n = 1;
      if(focusSci && typeof exoticCategoriesInCountry === 'function')
        for(const c of Object.keys(COUNTRIES_REG))
          n = Math.max(n, (exoticCategoriesInCountry(focusSci, c) || []).length);
      listEl.style.setProperty('--cp-exo', (n * 16 + (n - 1) * 3) + 'px');
    }
    const searchEl = backdrop.querySelector('.cp-search');
    const closeBtn = backdrop.querySelector('.cp-modal-close');

    const render = (filter = '') => {
      const fLC = filter.toLowerCase().trim();
      if(avecZones){
        backdrop.querySelectorAll('.cp-tab').forEach(t => t.classList.toggle('on', t.dataset.onglet === onglet));
        const onglZone = backdrop.querySelector('.cp-tab[data-onglet="zones"]');
        if(onglZone) onglZone.textContent = motZone(ccCourant);
        // Le champ dit ce qu'on y cherche, comme pour les pays. Le singulier est derive du
        // mot au pluriel qui sert deja d'etiquette a l'onglet, plutot que de reclamer un
        // second libelle a l'appelant.
        const mz = motZone(ccCourant);
        searchEl.placeholder = onglet === 'pays' ? 'Rechercher un pays…'
          : 'Rechercher ' + (_ZONE_SINGULIER[mz] || mz.toLowerCase()) + '…';
      }
      if(onglet === 'zones'){
        // Les lignes viennent de l'appelant : c'est lui qui sait quelle espece est affichee
        // et quelle zone est selectionnee. Le filtre se fait sur le rendu, ces listes tiennent
        // en une centaine de lignes.
        listEl.innerHTML = opts.zones(ccCourant)
          || '<div style="padding:16px; text-align:center; color:var(--ink-3);">Ce pays n\'a pas de découpage disponible.</div>';
        if(fLC) listEl.querySelectorAll('.reg-picker-item').forEach(r => {
          if(!r.textContent.toLowerCase().includes(fLC)) r.style.display = 'none';
        });
        return;
      }
      let html = '';
      // Largeur de la case des lettres : celle de la ligne qui en porte le plus. Une case
      // figee a trois lettres laisserait un grand vide sur les neuf dixiemes des lignes,
      // qui n'en ont qu'une ; une case libre decalerait la colonne des pourcentages des
      // qu'une ligne en porte deux. On la taille sur la liste elle-meme.
      // Sans espece courante, les lignes de pays montrent le nombre d'especes que leur bar
      // chart connait. Une barre le rend comparable d'un coup d'oeil, comme sur les lignes
      // de zone qui en ont une depuis toujours. Rapportee au plus fourni des pays listes.
      const nEspecesDe = (c) => {
        const r = COUNTRIES_REG[c];
        if(!r) return 0;
        return Object.keys((r.barTier && r.barTier()) || {}).length
            || Object.keys((r.st && r.st()) || {}).length;
      };
      const maxEspeces = focusSci ? 0 : Math.max(1, ...Object.keys(COUNTRIES_REG).map(nEspecesDe));
      for(const cont of CONTINENT_ORDER){
        const items = (grouped[cont] || []).filter(x => {
          const cc = x.cc;
          if(!fLC) return true;
          const name = (COUNTRIES_REG[cc].name || '').toLowerCase();
          return name.includes(fLC) || cc.toLowerCase().includes(fLC);
        });
        if(!items.length) continue;
        html += `<div class="cp-group-title">${esc(cont)}</div>`;
        for(const it of items){
          const cc = it.cc;
          const reg = COUNTRIES_REG[cc];
          // Retour a flagImg (img flagcdn) : sur Windows desktop les emoji drapeaux
          // tombent en fallback texte "FR"/"ME" illisible. flagImg garantit un rendu
          // uniforme cross-platform.
          const flag = flagImg(cc);
          let meta = '';
          let dotHtml = '';
          let titreLigne = '';
          if(focusSci){
            // Utilise le tier de rareté (merge S&T + bar chart via rarityForCountry) plutot
            // que la valeur brute (evite melange % vs ind/h). Affiche tier + label + couleur.
            // Espece consideree "absente" seulement si aucune data et PAS exotique CONFIRME
            // dans ce pays via eBird. Fix 2026-09-21 : n'utilise plus le fallback isExoticInCountry
            // (base sur EXOTIQUES_CONNUES_FR qui est FR-centric). Un pays != FR doit avoir une
            // entree explicite dans EXOTIQUES_EBIRD_PAR_PAYS[cc] pour etre considere "exotique
            // local". Sinon la Perruche a collier apparaissait comme 'N Introduit etabli' en
            // Islande / Sri Lanka via fallback FR alors qu'elle n'y est pas listee.
            const ebCC = EXOTIQUES_EBIRD_PAR_PAYS[cc] && EXOTIQUES_EBIRD_PAR_PAYS[cc][focusSci];
            // Un X isole (echappe anecdotique) est traite comme non-exotique local :
            // le picker doit afficher "absente" pour Diamant de Gould en Espagne, pas "X".
            const isExoLocal = ((cc === 'FR') ? isExoticInCountry(focusSci, cc) : !!ebCC)
              && !_isIsolatedXExotic(focusSci, cc);
            // Source de verite = rarityForCountry (meme calcul que la fiche espece).
            // Fix 2026-09-22 : avant, le picker basait "absente" sur it.score (max monthly
            // brut) alors que la fiche utilise rarityForCountry qui a des fallbacks
            // supplementaires (exotiques, REAL_RARITY legacy). Ex :
            // Dindon sauvage affichait tier 9 sur la fiche mais "absente" sur le picker.
            // On aligne : absent = rarityForCountry retourne 0 ET pas exotique local.
            const tier = rarityForCountry(focusSci, cc);
            const monCC = reg.monthly()[focusSci];
            // Meme bascule que la liste des zones : un mois choisi sur la carte se lit ici
            // aussi, sinon les deux onglets du meme selecteur ne parleraient pas de la meme
            // periode.
            const vAn = !Array.isArray(monCC) ? 0
              : (moisLu == null ? _valeurAnnuelleZone(monCC, cc) : (monCC[moisLu] || 0));
            // Un tag exotique sans la moindre ligne de bar chart ne prouve aucune presence :
            // il dit seulement qu'un reviewer a prevu un classement si l'espece se montre.
            // Meme regle que la fiche (noBarData), sans quoi le selecteur affichait « P » pour
            // l'Erismature a tete blanche au Royaume-Uni pendant que la fiche, juste derriere,
            // disait « jamais notee au Royaume-Uni entre 2019 et 2026 ».
            const absent = tier === 0 && (!isExoLocal || vAn === 0);
            const col = realColor(tier);
            // Chip letter : aligne le comportement sur la fiche espece (renderLine).
            // - Tier 0 exotique : affiche la lettre categorie (N/P/X/C)
            // - Tier > 0 et cat = N ou P : affiche N ou P (Etabli / Provisoire visibles
            //   sur les cartes Birdydex, coherent inter-vues)
            // - Autres : le chiffre du tier
            const localCat = ebCC || (cc === 'FR' ? _exoticCategory(focusSci) : '') || '';
            let lbl;
            if(absent) lbl = 'absente';
            else lbl = (typeof REAL_LABELS === 'object' && REAL_LABELS[tier]) || ('tier '+tier);
            // La pastille porte le PALIER, partout et sans exception - la vignette du
            // birdydex et la fiche le font deja. Les lettres du statut partent dans leurs
            // ronds gris de 16 px, les memes qu'ailleurs, poses AVANT le pourcentage :
            // elles disent d'ou sort l'oiseau, pas s'il est facile a voir.
            //
            // TOUS les statuts, et non le seul retenu au national : le pays qui classe une
            // espece N quelque part et X ailleurs porte les deux lettres, a la suite, comme
            // la vignette du birdydex le fait deja. On n'en montrait qu'un, et seulement
            // s'il etait N ou P - un X ne s'affichait jamais.
            const catsPays = (typeof exoticCategoriesInCountry === 'function')
              ? (exoticCategoriesInCountry(focusSci, cc) || []) : [];
            const catsLigne = catsPays.length ? catsPays : (localCat ? [localCat] : []);
            const exoChip = catsLigne.map(c => jetonExo(c)).join('');
            // Nouveau format : label texte AVANT le chip numero pour que les chips
            // soient tous alignes a droite (ex: "Rare [7]"). Absent = pas de chip.
            // Meme lecture que les lignes de zone : la valeur annuelle, sa barre, puis le
            // palier - et la meme fonction pour les fabriquer, pour qu'elles ne divergent pas.
            // La valeur est celle qui fonde le palier national : la part des listes du pays qui
            // citent l'espece, ponderee par l'effort mensuel. Pas le pic, qui dirait autre chose
            // que la couleur posee a cote.
            //
            // Le libelle ("Omnipresent", "Introduit etabli") passe en infobulle : il repetait le
            // plus souvent ce que le palier dit deja, et il empechait d'aligner les deux listes
            // du meme selecteur.
            const barW = _longueurBarre(vAn);
            titreLigne = (reg.name || cc) + ' — ' + lbl
              + (vAn > 0 ? ' · ' + fmtPct(vAn) + ' des listes sur l\'année' : '');
            // La place du rond est reservee meme quand il n'y a pas de statut, sinon les
            // pourcentages ne s'alignaient plus d'une ligne a l'autre.
            const caseExo = '<span class="cp-item-exo">' + exoChip + '</span>';
            meta = absent
              ? caseExo + '<span class="reg-picker-val">absente</span><div class="reg-picker-bar"></div>'
                + tierChip('–', 'var(--line-2)', { cls: 'tier-rond' })
              : caseExo + '<span class="reg-picker-val">' + esc(fmtPct(vAn)) + '</span>'
                + '<div class="reg-picker-bar"><div style="width:' + barW + '%; color:' + col + ';"></div></div>'
                + tierChip(tier, col, { title: 'palier ' + tier, cls: 'tier-rond' });
          } else {
            // Nb d'especes calibrees pour ce pays = le bar chart, qui est la source de la
            // rarete dans les 16 pays. On primait le S&T en le croyant plus riche : il ne
            // l'est pas, il compte 171 a 450 especes de MOINS selon le pays. Les 6 pays
            // pourvus d'un S&T affichaient donc un nombre plus petit que les 10 autres,
            // qui tombaient deja sur le bar chart (l'Espagne annoncait 284 especes contre
            // 694 reelles). Le bar chart partout, c'est comparable.
            const nSp = nEspecesDe(cc);
            meta = '<span class="cp-item-exo"></span>'
              + (nSp > 0
                  ? `<span class="cp-item-meta">${nSp} esp.</span>`
                    + `<div class="reg-picker-bar"><div style="width:${Math.round(nSp / maxEspeces * 100)}%; color:var(--accent);"></div></div>`
                  : '<span></span><span></span>');
          }
          // Fix 2026-09-22 : absentCls doit refléter le vrai statut 'absent' (tier === 0
           // ET pas exotique local) au lieu de it.score seul. Sinon FR avec tier 7 via
          // S&T Cornell mais aucune data monthly apparaît grisée à tort.
          const absentCls = focusSci && typeof absent !== 'undefined' && absent ? ' absent' : '';
          html += `<div class="cp-item${focusSci ? '' : ' sans-palier'}${cc === ccCourant ? ' on' : ''}${absentCls}" data-cc="${esc(cc)}"${titreLigne ? ` data-tip="${esc(titreLigne)}"` : ''}>
            <span class="cp-item-flag">${flag}</span>
            <span class="cp-item-name">${esc(reg.name || cc)}</span>
            ${meta}
          </div>`;
        }
      }
      listEl.innerHTML = html || '<div style="padding:16px; text-align:center; color:var(--ink-3);">Aucun pays trouvé.</div>';
    };
    render();
    // Les frequences mensuelles des pays etrangers vivent dans un fichier a part depuis le
    // 2026-09-27, et ce selecteur est le seul endroit qui les veuille TOUTES a la fois. Si
    // elles ne sont pas encore arrivees, chaque ligne afficherait « - » : on redessine des
    // qu'elles sont la, plutot que de retarder l'ouverture du selecteur.
    if(!_donneesPaysPretes()){
      _chargerDonneesPays().then(() => { try{ render(); }catch(_){} });
    }
    // Events
    const cleanup = () => {
      backdrop.remove();
      document.removeEventListener('keydown', escHandler);
      clearTimeout(minuteurSurvol);   // pas de prechargement declenche apres fermeture
    };
    const escHandler = e => { if(e.key === 'Escape'){ cleanup(); resolve(null); } };
    document.addEventListener('keydown', escHandler);
    backdrop.addEventListener('click', e => {
      if(e.target === backdrop){ cleanup(); resolve(null); }
    });
    closeBtn.addEventListener('click', () => { cleanup(); resolve(null); });
    searchEl.addEventListener('input', () => render(searchEl.value));
    // Precharge les frequences regionales d'un pays avant qu'on le clique. Elles pesent
    // 2,6 Mo pour la France : les demander au survol laisse le temps du trajet souris-clic,
    // souvent assez pour que la liste des zones s'affiche deja remplie.
    // opts.precharger ne doit rien appliquer, juste charger - sinon survoler changerait
    // le pays courant. La memoisation est faite par l'appelant (_freqDataPromises), un
    // second appel ne coute rien.
    const dejaDemande = new Set();
    let minuteurSurvol = null;
    const precharger = (cc) => {
      if(!cc || dejaDemande.has(cc) || typeof opts.precharger !== 'function') return;
      dejaDemande.add(cc);
      try { Promise.resolve(opts.precharger(cc)).catch(() => {}); } catch(_) {}
    };
    precharger(ccCourant);
    listEl.addEventListener('mouseover', e => {
      const it = e.target.closest('.cp-item');
      if(!it || !it.dataset.cc) return;
      // Un delai court : sans lui, faire defiler la liste declencherait les 53 pays.
      clearTimeout(minuteurSurvol);
      const cc = it.dataset.cc;
      minuteurSurvol = setTimeout(() => precharger(cc), 120);
    });
    const tabsEl = backdrop.querySelector('.cp-tabs');
    if(tabsEl) tabsEl.addEventListener('click', e => {
      const t = e.target.closest('.cp-tab');
      if(!t) return;
      onglet = t.dataset.onglet;
      searchEl.value = '';
      render();
    });
    listEl.addEventListener('click', async e => {
      const zone = e.target.closest('.reg-picker-item');
      if(zone && avecZones){ cleanup(); resolve({ type: 'zone', code: zone.dataset.code || '' }); return; }
      const it = e.target.closest('.cp-item');
      if(!it || it.classList.contains('disabled')) return;
      const cc = it.dataset.cc;
      if(!avecZones){ cleanup(); resolve(cc); return; }
      // Choisir un pays ne ferme pas le modal et ne change pas d'onglet : on applique, et
      // la liste des pays reste a l'ecran, le nouveau pays surligne. Elle basculait
      // automatiquement sur les zones, en supposant qu'on avait change de pays pour y
      // descendre - ce qui n'est vrai que parfois, et enlevait la main a qui voulait
      // simplement comparer deux pays ou corriger un clic.
      if(cc !== ccCourant){
        it.style.opacity = '.5';
        // On n'attend PAS la fin du chargement pour redessiner. Les frequences regionales
        // pesent 2,6 Mo pour la France et 2,3 pour le Royaume-Uni : le modal restait fige
        // une seconde entiere apres le clic. On marque le pays tout de suite, et on
        // redessine une seconde fois quand les valeurs arrivent.
        const chargement = opts.onPays(cc);
        ccCourant = cc;
        searchEl.value = '';
        render();
        try { await chargement; } catch(_) {}
        // Le modal a pu etre ferme pendant le telechargement.
        if(!backdrop.isConnected) return;
        render();
        return;
      }
      // Reclic sur le pays deja choisi : rien a appliquer, on redessine simplement.
      searchEl.value = '';
      render();
    });
    document.body.appendChild(backdrop);
    setTimeout(() => searchEl.focus(), 50);
  });
}
// Modal picker generique (meme style que _openCountryPicker) pour les filtres de type
// select (famille, habitat, statut coche). Retourne la value choisie (peut etre '' pour
// 'Toutes / Tous'), ou null si annule.
//
//   opts = { title, options: [{value, label, count?, color?}], searchable }
//
// options[0] est generalement l'option "Tous / Toutes" (value = '').
function _openFilterPicker(currentValue, opts){
  return new Promise(resolve => {
    const { title = 'Choisir', options = [], searchable = true } = opts || {};
    const backdrop = document.createElement('div');
    backdrop.className = 'cp-modal-backdrop';
    backdrop.innerHTML = `
      <div class="cp-modal-inner">
        <div class="cp-modal-title">
          <span>${esc(title)}</span>
          <button type="button" class="cp-modal-close" aria-label="Fermer">×</button>
        </div>
        ${searchable ? `<input type="search" class="cp-search" placeholder="Rechercher…" autofocus>` : ''}
        <div class="cp-list"></div>
      </div>`;
    const listEl = backdrop.querySelector('.cp-list');
    const searchEl = backdrop.querySelector('.cp-search');
    const closeBtn = backdrop.querySelector('.cp-modal-close');
    const render = (filter = '') => {
      const fLC = filter.toLowerCase().trim();
      const items = options.filter(o => !fLC || (o.label || '').toLowerCase().includes(fLC));
      if(!items.length){
        listEl.innerHTML = '<div style="padding:16px; text-align:center; color:var(--ink-3);">Aucune option trouvée.</div>';
        return;
      }
      listEl.innerHTML = items.map(o => {
        const on = (o.value === currentValue) ? ' on' : '';
        const dot = o.color ? `<span class="cp-item-dot" style="background:${o.color};"></span>` : '';
        const cnt = (o.count != null) ? `<span class="cp-item-meta">${o.count} esp.</span>` : '';
        // cp-item-simple : ce selecteur generique ne pose que deux ou trois elements, quand
        // .cp-item dessine depuis la grille a six colonnes du selecteur de pays. Sans lui, le
        // libelle tombait dans la colonne du drapeau, large de 28 px, et « Par famille » se
        // lisait « P… ».
        return `<div class="cp-item cp-item-simple${on}" data-value="${esc(String(o.value))}">
          ${dot}
          <span class="cp-item-name">${esc(o.label)}</span>
          ${cnt}
        </div>`;
      }).join('');
    };
    render();
    const cleanup = () => {
      backdrop.remove();
      document.removeEventListener('keydown', escHandler);
    };
    const escHandler = e => { if(e.key === 'Escape'){ cleanup(); resolve(null); } };
    document.addEventListener('keydown', escHandler);
    backdrop.addEventListener('click', e => { if(e.target === backdrop){ cleanup(); resolve(null); } });
    closeBtn.addEventListener('click', () => { cleanup(); resolve(null); });
    if(searchEl) searchEl.addEventListener('input', () => render(searchEl.value));
    listEl.addEventListener('click', e => {
      const it = e.target.closest('.cp-item');
      if(!it) return;
      cleanup();
      resolve(it.dataset.value);
    });
    document.body.appendChild(backdrop);
    if(searchEl) setTimeout(() => searchEl.focus(), 50);
  });
}
