// Milieux masques partout : chips de la fiche, filtre Birdydex, index inverses, trophees.
// 'aerial' decrit un mode de deplacement (martinets, hirondelles) plutot qu'un milieu, et
// n'aide pas a savoir ou chercher l'oiseau. Les 820 especes concernees en ont toutes au
// moins un autre, aucune ne se retrouve sans milieu.
const HABITATS_MASQUES = new Set(['aerial']);
function habitatsOf(sci){
  const key = (sci||"").trim().toLowerCase();
  // Override total AVONET (cas ou la classification de base est fausse).
  const override = HABITAT_OVERRIDES[key];
  const base = HABITATS[key];
  const add = HABITAT_ADDITIONS[key];
  let cats;
  if(override) cats = override;
  else if(!base && !add) return null;
  else if(!add) cats = base;
  else if(!base) cats = add;
  else cats = [...new Set([...base, ...add])];   // fusion sans doublons
  const visibles = cats.filter(c => !HABITATS_MASQUES.has(c));
  return visibles.length ? visibles : null;
}
