  // au lieu du fallback curatorial EXOTIQUES_CONNUES_FR (retire). Cover 116 vs 82 especes.
  return !!(EXOTIQUES_EBIRD_PAR_PAYS.FR && EXOTIQUES_EBIRD_PAR_PAYS.FR[k]);
