  // Si EXOTIQUES_EBIRD_PAR_PAYS explicite l'a marquee exotique, on considere qu'elle n'est pas native.
  if(EXOTIQUES_EBIRD_PAR_PAYS[cc] && EXOTIQUES_EBIRD_PAR_PAYS[cc][k]) return false;
