// Une espece entre au catalogue d'un pays si elle y a ete vue au moins 3 annees sur 8.
//
// En dessous, c'est un accidentel ou un echappe : en France les 79 especes vues une seule
// annee sont des Ara militaire, Cacatoes rosalbin, Canard de Chine, Albatros a sourcils
// noirs. On ne va pas les "chercher", elles ne sont pas des cibles. Les 39 vues deux annees
// sont de la meme nature — le Bec-croise d'Ecosse, endemique britannique, y figure.
//
// A partir de trois annees on trouve des raretes que les birders chassent reellement quand
// l'alerte tombe : Busard des marais, Becasseau minuscule, Oie empereur, Courvite isabelle.
//
// Le seuil reste bas volontairement, a cause des especes IRRUPTIVES : le Jaseur boreal,
// absent plusieurs annees puis envahissant, n'apparait que 5 annees sur 8. Tout seuil a 6
// ou plus l'ecarterait a tort.
//
// Sans donnee pour un pays, on ne filtre pas : mieux vaut un catalogue trop large qu'un
// catalogue ampute par une absence de mesure.
const _MIN_ANNEES_CATALOGUE = 3;
function _estReguliere(sci, cc){
  const parPays = (typeof ANNEES_PRESENCE === 'object') ? ANNEES_PRESENCE[cc || 'FR'] : null;
  if(!parPays || !Object.keys(parPays).length) return true;
  const k = (sci || '').trim().toLowerCase();
  const n = parPays[k] != null ? parPays[k] : parPays[(typeof SCI_ALIAS === 'object' && SCI_ALIAS[k]) || k];
  return (n || 0) >= _MIN_ANNEES_CATALOGUE;
}

// « en France » mais « au Royaume-Uni » et « aux États-Unis » : le genre et le nombre du nom
// de pays commandent la preposition, on ne peut pas la coller mecaniquement.
const _PREP_PAYS = { ME:'au', GB:'au', PT:'au', CA:'au', LK:'au', US:'aux' };
function _auPays(cc){
  const nom = (COUNTRIES_REG[cc] && COUNTRIES_REG[cc].name) || cc;
  return `${_PREP_PAYS[cc] || 'en'} ${nom}`;
}

function hasRarityCalibrationInCountry(sci, country){
  const k = (sci||'').trim().toLowerCase();
  const cc = country || 'FR';
  // Une espece accidentelle n est pas une cible : elle sort des listes « a trouver ».
  // Les trois appelants de cette fonction ne listent que des especes NON vues, donc une
  // observation deja cochee n est jamais concernee.
  if(!_estReguliere(k, cc)) return false;
  if(cc === 'ME'){
    return (typeof REAL_RARITY_ME_EBIRD !== 'undefined' && !!REAL_RARITY_ME_EBIRD[k])
      || isExoticInCountry(k, 'ME');
  }
  // FR (par defaut) : bar chart FR OU exotique (curated ou eBird API per-pays)
  return !!REAL_RARITY[k] || isExoticInCountry(k, 'FR');
}
// Met a jour le hint sous les ctrls carte qui explicite la calibration rarete utilisee.
// Affiche seulement si country != FR (pour FR c'est evident, pas besoin de le dire).
function _updateCountryHint(){
  const el = document.getElementById('mapCountryHint'); if(!el) return;
  const c = (typeof ebFilter !== 'undefined' && ebFilter.country) || 'FR';
  if(c === 'FR'){ el.style.display = 'none'; el.innerHTML = ''; return; }
  const flg = flagImg(c) || '';
  const wrap = `<span style="display:inline-block;vertical-align:middle;margin-right:6px;">${flg}</span>`;
  // Les 16 pays sont desormais calibres sur la meme mesure, le bar chart eBird 2019-2026.
  // Le message disait encore que seul le Montenegro l'etait et que la France ajoutait du
  // Status & Trends : les deux branches etaient fausses.
  const nom = (COUNTRIES_REG[c] && COUNTRIES_REG[c].name) || c;
  el.innerHTML = `${wrap} Rareté calibrée pour ${esc(nom)} sur le bar chart eBird 2019-2026, même échelle que la France.`;
  el.style.display = '';
}
// Rareté par pays. Passe explicitement 'FR' ou 'ME' etc. Retourne 0 si pas calibre pour
