const RIVAGES_G=/^(charadrius|pluvialis|vanellus|anarhynchus|eudromias|erythrogonys|elseyornis|thinornis|haematopus|recurvirostra|himantopus|burhinus|glareola|cursorius|rostratula|jacana|hydrophasianus|actophilornis|irediparra|metopidius|microparra|pluvianellus|pluvianus|dromas|attagis|thinocorus|ibidorhyncha|chionis)$/;
// Turdidae : grives, merles. Rockthrush (Monticola) est Muscicapidae en taxo moderne.
const TURDIDAE_G=/^(turdus|catharus|hylocichla|ixoreus|ridgwayia|zoothera|geokichla|sialia|myadestes|neocossyphus|nesocichla|cataponera|psophocichla|cichlopsis|entomodestes|myioborus|chlamydochaera|cochoa|monticola)$/;
// Muscicapidae : rossignols, rougegorge, rougequeues, traquets, tariers, gobemouches.
const MUSCICAPIDAE_G=/^(luscinia|phoenicurus|oenanthe|saxicola|muscicapa|ficedula|erithacus|cyanecula|cercotrichas|copsychus|calliope|larvivora|brachypteryx|sheppardia|myrmecocichla|tarsiger|irania|myophonus|enicurus|culicicapa|niltava|cyornis|eumyias|melaenornis|bradornis|fraseria|dioptrornis|humblotia|myioparus|empidornis|namibornis|cassiornis|ficedulinae|rhinomyias|anthipes|erythrocichla|leonardina|kittacincla|trichixos|drymodes|trichastoma|monachella|monticoloides|myrmecocichla|thamnolaea|oenanthe|campicoloides|pinarornis|saxicoloides|lioparus|niltava|ficedula|muscicapella)$/;
// Sylviidae strict : fauvettes (Sylvia, Curruca depuis split IOC 2020), parisoma.
const SYLVIIDAE_G=/^(sylvia|curruca|parisoma|chamaea|myzornis|sylviaparinae|hornbillhrophaenicula|argus|sylvietta|rhopophilus)$/;
// Pouillots (Phylloscopidae) + rousserolles/hypolais (Acrocephalidae) +
// locustelles (Locustellidae) + bouscarles (Cettiidae). Groupes ensemble.
const POUILLOTS_ROUSSEROLLES_G=/^(phylloscopus|seicercus|rhadina|abrornis|acrocephalus|hippolais|iduna|chloropeta|calamocichla|nesillas|locustella|bradypterus|robsonius|elaphrornis|cincloramphus|megalurus|schoenicola|helopsaltes|dromaeocercus|amphilais|cettia|horornis|urosphena|tesia|tickellia|abroscopus|phyllergates|hemitesia|erythrocercus|neomixis|scotocerca|hylia|pnoepyga)$/;
// Fringillidae : pinsons, chardonnerets, verdiers, tarins, linottes, bec-croises,
// bouvreuils, grosbecs, roselins.
const FRINGILLIDAE_G=/^(fringilla|coccothraustes|carpodacus|chloris|serinus|linaria|spinus|carduelis|loxia|pyrrhula|bucanetes|rhodospiza|acanthis|chrysocorythus|rhodopechys|eremopsaltria|uragus|loxioides|palmeria|himatione|vestiaria|drepanis|loxops|hemignathus|telespiza|paroreomyza|pseudonestor|melamprosops|magumma|eophona|mycerobas|hesperiphona|pinicola|pyrrhoplectes|leucosticte|haemorhous|callacanthis|rhynchostruthus|spinus|linurgus|callanthis|linaria|carpodacus|callacanthis|neospiza|crithagra|serinus)$/;
// Emberizidae + Passerellidae (bruants + sparrows NW) : bruants europeens et
// sparrows americains ont ete regroupes traditionnellement.
const EMBERIZIDAE_G=/^(emberiza|plectrophenax|calcarius|melophus|latoucheornis|schoeniclus|spizella|melospiza|ammodramus|chondestes|junco|zonotrichia|passerella|pipilo|aimophila|passerculus|calamospiza|amphispiza|artemisiospiza|spizelloides|peucaea|ammospiza|pooecetes|xenospiza|centronyx|arremon|arremonops|atlapetes|pselliophorus|melozone|torreornis|oriturus|rhynchospiza|piezorhina|tiaris)$/;
// Rallidae : foulques, poules d'eau, rales, marouettes, taleves, gallinules.
const RALLIDAE_G=/^(fulica|gallinula|rallus|zapornia|porzana|crex|porphyrio|paragallinula|amaurornis|aramides|neocrex|laterallus|coturnicops|micropygia|rallina|anurolimnas|sarothrura|himantornis|canirallus|dryolimnas|aramidopsis|eulabeornis|hypotaenidia|habroptila|cabalus|nesoclopeus|diaphorapteryx|aphanapteryx|gymnocrex|gallirallus|pardirallus|mundia|cyanolimnas|porphyrula|tribonyx|amaurolimnas|notornis|atlantisia|rougetius|habropteryx)$/;
// Laridae (goelands, mouettes, sternes) + Stercorariidae (labbes) : traditionnellement
// associes, memes eaux, meme ordre Charadriiformes. 4 esp de labbes en FR pelagique.
const LARIDAE_G=/^(larus|ichthyaetus|chroicocephalus|hydrocoloeus|leucophaeus|rissa|xema|pagophila|rhodostethia|sterna|sternula|thalasseus|gelochelidon|hydroprogne|onychoprion|chlidonias|anous|gygis|creagrus|saundersilarus|stercorarius|catharacta)$/;
// Motacillidae : bergeronnettes (Motacilla) + pipits (Anthus) + genres tropicaux.
const MOTACILLIDAE_G=/^(motacilla|anthus|dendronanthus|tmetothylacus|macronyx|amaurocichla|hemimacronyx)$/;
// Cigognes (Ciconiidae) + Ibis/spatules (Threskiornithidae) : grands echassiers a long bec.
// Regroupement thematique/ecologique (les deux familles sont dans des ordres differents en taxo moderne).
// Cigognes (Ciconiidae, Ciconiiformes) + Grues (Gruidae, Gruiformes). Deux ordres distincts
// mais grands migrateurs a cou tendu, silhouette elancee, vol en V. Ecologique/visuel tres coherent.
// FR 3 (Cigogne blanche, Cigogne noire, Grue cendree) / monde ~35.
const ECHASSIERS_G=/^(ciconia|ephippiorhynchus|jabiru|leptoptilos|mycteria|anastomus|grus|antigone|balearica|bugeranus|leucogeranus|anthropoides)$/;
// Coraciiformes hors martins-pecheurs : guepiers (Meropidae) + rolliers (Coraciidae) +
// brachypterolles (Brachypteraciidae) + motmots (Momotidae) + todiers (Todidae).
// Guepier & Rollier d'Europe presents en FR ; autres tropicaux.
const CORACIIFORMES_G=/^(merops|nyctyornis|meropogon|coracias|eurystomus|brachypteracias|atelornis|uratelornis|geobiastes|hylomanes|aspatha|electron|eumomota|baryphthengus|momotus|todus)$/;
// Ordre Suliformes complet : Phalacrocoracidae (cormorans) + Sulidae (fous) +
// Anhingidae (anhingas) + Fregatidae (fregates). ~5 esp FR (3 cormorans + 1 fou de Bassan
// + 1 fregate rare). Monde ~60. Pelicans exclus (Pelecaniformes moderne = herons+ibis+pelicans).
const SULIFORMES_G=/^(phalacrocorax|microcarbo|nannopterum|gulosus|urile|leucocarbo|poikilocarbo|compsohalieus|sula|morus|papasula|anhinga|fregata|hypoleucos)$/;
// Superfamille Sturnoidea : Sturnidae (etourneaux) + Mimidae (moqueurs) + Buphagidae (piqueboeufs)
// + Rhabdornithidae (rhabdornis). FR ~3 esp (etourneaux) / monde ~160.
const STURNOIDEA_G=/^(sturnus|pastor|acridotheres|gracula|sturnia|saroglossa|aplonis|poeoptera|grafisia|onychognathus|lamprotornis|cinnyricinclus|speculipastor|spreo|neocichla|creatophora|basilornis|sarcops|streptocitta|enodes|scissirostrum|hylopsar|notopholia|leucopsar|ampeliceps|goodfellowia|mino|scissirostrum|mimus|toxostoma|melanotis|ramphocinclus|cinclocerthia|margarops|allenia|nesomimus|dumetella|mimodes|oreoscoptes|buphagus|rhabdornis)$/;
// Moineaux (Passeridae) + accenteurs (Prunellidae). Meme superfamille Passeroidea,
// ecologiquement proches (petits granivores/insectivores discrets brun-gris). FR ~7 / monde ~55.
const MOINEAUX_ACCENTEURS_G=/^(passer|petronia|carpospiza|pyrgilauda|onychostruthus|montifringilla|gymnoris|hypocryptadius|prunella)$/;
// Grebes (Podicipedidae). FR 5 (castagneux, huppe, jougris, oreillard, esclavon) / monde ~23.
const PODICIPEDIDAE_G=/^(podiceps|tachybaptus|podilymbus|aechmophorus|rollandia|poliocephalus)$/;
// Procellariiformes complet : Diomedeidae (albatros) + Procellariidae (puffins, petrels,
// fulmars, prions) + Hydrobatidae/Oceanitidae (oceanites nord/sud). 100% pelagiques.
// FR ~10 (Puffin cendre, Puffin des Baleares, Puffin des Anglais, Puffin fuligineux, Fulmar boreal,
// Petrel diablotin, Oceanite tempete, Oceanite culblanc, quelques rares...) / monde ~150.
const PROCELLARIIFORMES_G=/^(diomedea|thalassarche|phoebastria|phoebetria|puffinus|ardenna|calonectris|procellaria|bulweria|pterodroma|fulmarus|macronectes|daption|halobaena|pachyptila|aphrodroma|pagodroma|thalassoica|lugensa|pseudobulweria|hydrobates|oceanodroma|oceanites|pelagodroma|fregetta|nesofregetta|garrodia)$/;
// Outardes (Otididae, Otidiformes) + Gangas (Pteroclidae, Pteroclidiformes). Deux ordres
// distincts mais ecologiquement identiques : oiseaux terrestres cryptiques des plaines et
// steppes seches, silhouette compacte au sol, camouflage puis decollage bruyant.
// FR 4 (Outarde canepetiere, Grande Outarde rare, Ganga cata, Ganga unibande) / monde ~42.
// Coucous (Cuculidae). FR 2 (coucou gris, coucou geai) / monde ~150.
const CUCULIDAE_G=/^(cuculus|clamator|coccyzus|chrysococcyx|cacomantis|hierococcyx|phaenicophaeus|cercococcyx|surniculus|eudynamys|urodynamis|scythrops|microdynamis|morococcyx|dromococcyx|tapera|geococcyx|neomorphus|crotophaga|guira|coua|centropus|carpococcyx|ceuthmochares|saurothera|hyetornis|piaya|pachycoccyx|chalcites|penthoceryx)$/;
// Caprimulgiformes elargi : engoulevents + ibijaux + podarges + podarges d'Australasie
// + guacharo. Tous nocturnes/crepusculaires, insectivores aeriens ou frugivores. FR 2 / monde ~140.
const CAPRIMULGIFORMES_G=/^(caprimulgus|chordeiles|phalaenoptilus|siphonorhis|hydropsalis|uropsalis|macropsalis|nyctidromus|lyncornis|eurostopodus|gactornis|nyctipolus|eleothreptus|systellura|setopagis|nyctiphrynus|antrostomus|veles|nyctibius|podargus|batrachostomus|rigidipenna|aegotheles|steatornis)$/;
// Superfamille Certhioidea : Sittidae (sittelles + tichodrome) + Certhiidae (grimpereaux) +
// Salpornithidae (grimpereau tachete africain) + Troglodytidae (troglodyte + wrens NM) +
// Polioptilidae (gobemoucherons). Petits explorateurs d'ecorce et de buissons.
// FR ~6 (Sitelle torchepot, Sitelle corse, Tichodrome, Grimpereaux jardins/bois, Troglodyte). Monde ~140.
const CERTHIOIDEA_G=/^(sitta|tichodroma|certhia|salpornis|troglodytes|nannus|cistothorus|thryothorus|cantorchilus|henicorhina|thryomanes|campylorhynchus|pheugopedius|salpinctes|catherpes|microcerculus|uropsila|odontorchilus|cyphorhinus|hylorchilus|ferminia|thryorchilus|polioptila|ramphocaenus|microbates)$/;
// Predicat de famille pour le modal des familles d'especes (bouton Monde/France).
// Retourne true si l'espece appartient a la famille. Utilise pour filtrer le pool FR
// via REAL_ABUNDANCE_ST_FR : intersection de (sci matche predicate) x (abondance FR > 0).
const SPECIES_FAMILY_FILTERS = {
  rapaces: sci => {
    const g = (sci||'').split(' ')[0];
    if(RAPTOR_G.test(g)) return true;
    const fam = (typeof familyOf === 'function') ? familyOf(sci) : null;
    return fam === 'Balbuzard' || fam === 'Rapaces (aigles, buses…)' || fam === 'Faucons' || fam === 'Vautours du Nouveau Monde';
  },
  nocturnes: sci => {
    const g = (sci||'').split(' ')[0];
    if(OWL_G.test(g)) return true;
    const fam = (typeof familyOf === 'function') ? familyOf(sci) : null;
    return fam === 'Effraies' || fam === 'Chouettes, hiboux';
  },
  anatidae: sci => {
    const g = (sci||'').split(' ')[0];
    if(ANATIDAE_G.test(g) || PODICIPEDIDAE_G.test(g)) return true;
    const fam = (typeof familyOf === 'function') ? familyOf(sci) : null;
    return fam === 'Canards, oies, cygnes' || fam === 'Grèbes';
  },
  hirundinidae: sci => {
    const g = (sci||'').split(' ')[0];
    if(HIRUNDO_G.test(g) || MARTINETS_G.test(g)) return true;
    const fam = (typeof familyOf === 'function') ? familyOf(sci) : null;
    return fam === 'Hirondelles' || fam === 'Martinets';
  },
  martinets: sci => {
    const g = (sci||'').split(' ')[0];
    if(MARTINETS_G.test(g)) return true;
    const fam = (typeof familyOf === 'function') ? familyOf(sci) : null;
    return fam === 'Martinets';
  },
  alaudidae: sci => {
    const g = (sci||'').split(' ')[0];
    if(ALAUDA_G.test(g)) return true;
    const fam = (typeof familyOf === 'function') ? familyOf(sci) : null;
    return fam === 'Alouettes' || fam === 'Panure';
  },
  paridae: sci => {
    const g = (sci||'').split(' ')[0];
    if(PARIDAE_G.test(g) || CERTHIOIDEA_G.test(g)) return true;
    const fam = (typeof familyOf === 'function') ? familyOf(sci) : null;
    return fam === 'Mésanges' || fam === 'Mésanges à longue queue' || fam === 'Rémiz'
      || fam === 'Sittelles' || fam === 'Tichodrome' || fam === 'Grimpereaux' || fam === 'Troglodytes' || fam === 'Gobemoucherons' || (fam && fam.startsWith('Grimpereaux'));
  },
  corvidae: sci => {
    const g = (sci||'').split(' ')[0];
    if(CORVIDAE_G.test(g)) return true;
    const fam = (typeof familyOf === 'function') ? familyOf(sci) : null;
    return fam === 'Corvidés' || fam === 'Corbeaux, geais, pies';
  },
  alcedinidae: sci => {
    const g = (sci||'').split(' ')[0];
    if(ALCEDI_G.test(g)) return true;
    const fam = (typeof familyOf === 'function') ? familyOf(sci) : null;
    return fam === 'Martins-pêcheurs';
  },
  ardeidae: sci => {
    const g = (sci||'').split(' ')[0];
    if(ARDEIDAE_G.test(g) || ECHASSIERS_G.test(g)) return true;
    const fam = (typeof familyOf === 'function') ? familyOf(sci) : null;
    // Grands echassiers = Pelecaniformes (herons, ibis, pelicans...) + Ciconiiformes (cigognes) + Gruiformes (grues).
    return fam === 'Hérons, aigrettes, butors' || fam === 'Hérons, aigrettes' || fam === 'Ibis, spatules' || fam === 'Pélicans' || fam === 'Ombrette' || fam === 'Bec-en-sabot du Nil' || fam === 'Cigognes' || fam === 'Grues';
  },
  columbidae: sci => {
    const g = (sci||'').split(' ')[0];
    if(COLUMBIDAE_G.test(g)) return true;
    const fam = (typeof familyOf === 'function') ? familyOf(sci) : null;
    return fam === 'Pigeons, tourterelles';
  },
  galliformes: sci => {
    const g = (sci||'').split(' ')[0];
    if(GALLIFORMES_G.test(g)) return true;
    const fam = (typeof familyOf === 'function') ? familyOf(sci) : null;
    return fam === 'Faisans, perdrix, tétras' || fam === 'Colins' || fam === 'Pintades' || fam === 'Megapodes';
  },
  picidae: sci => {
    const g = (sci||'').split(' ')[0];
    if(PICIDAE_G.test(g)) return true;
    const fam = (typeof familyOf === 'function') ? familyOf(sci) : null;
    return fam === 'Pics';
  },
  scolopacidae: sci => {
    const g = (sci||'').split(' ')[0];
    if(SCOLOPACIDAE_G.test(g)) return true;
    const fam = (typeof familyOf === 'function') ? familyOf(sci) : null;
    return fam === 'Chevaliers, bécasseaux' || fam === 'Bécasses, bécassines';
  },
  rivages: sci => {
    const g = (sci||'').split(' ')[0];
    if(RIVAGES_G.test(g)) return true;
    const fam = (typeof familyOf === 'function') ? familyOf(sci) : null;
    return fam === 'Pluviers, vanneaux' || fam === 'Huîtriers' || fam === 'Avocettes, échasses' || fam === 'Œdicnèmes' || fam === 'Glaréoles, courvites' || fam === 'Rhynchée' || fam === 'Jacanas';
  },
  turdidae: sci => {
    const g = (sci||'').split(' ')[0];
    if(TURDIDAE_G.test(g) || MUSCICAPIDAE_G.test(g)) return true;
    const fam = (typeof familyOf === 'function') ? familyOf(sci) : null;
    return fam === 'Grives, merles' || fam === 'Jaseurs' || fam === 'Gobemouches, rossignols, traquets' || fam === 'Rossignols, rougequeues' || fam === 'Gobemouches';
  },
  muscicapidae: sci => {
    const g = (sci||'').split(' ')[0];
    if(MUSCICAPIDAE_G.test(g)) return true;
    const fam = (typeof familyOf === 'function') ? familyOf(sci) : null;
    return fam === 'Gobemouches, rossignols, traquets' || fam === 'Rossignols, rougequeues' || fam === 'Gobemouches';
  },
  sylviidae: sci => {
    const g = (sci||'').split(' ')[0];
    if(SYLVIIDAE_G.test(g)) return true;
    const fam = (typeof familyOf === 'function') ? familyOf(sci) : null;
    return fam === 'Fauvettes';
  },
  phylloscopidae: sci => {
    const g = (sci||'').split(' ')[0];
    if(POUILLOTS_ROUSSEROLLES_G.test(g) || SYLVIIDAE_G.test(g)) return true;
    const fam = (typeof familyOf === 'function') ? familyOf(sci) : null;
    return fam === 'Pouillots' || fam === 'Rousserolles, hypolaïs' || fam === 'Locustelles' || fam === 'Bouscarles' || fam === 'Fauvettes';
  },
  fringillidae: sci => {
    const g = (sci||'').split(' ')[0];
    if(FRINGILLIDAE_G.test(g)) return true;
    const fam = (typeof familyOf === 'function') ? familyOf(sci) : null;
    return fam === 'Fringilles';
  },
  emberizidae: sci => {
    const g = (sci||'').split(' ')[0];
    if(EMBERIZIDAE_G.test(g) || FRINGILLIDAE_G.test(g)) return true;
    const fam = (typeof familyOf === 'function') ? familyOf(sci) : null;
    return fam === 'Bruants' || fam === 'Bruants du Nouveau Monde' || fam === 'Fringilles';
  },
  rallidae: sci => {
    const g = (sci||'').split(' ')[0];
    if(RALLIDAE_G.test(g)) return true;
    const fam = (typeof familyOf === 'function') ? familyOf(sci) : null;
    return fam === 'Râles, foulques';
  },
  laridae: sci => {
    const g = (sci||'').split(' ')[0];
    if(LARIDAE_G.test(g)) return true;
    const fam = (typeof familyOf === 'function') ? familyOf(sci) : null;
    return fam === 'Goélands, mouettes' || fam === 'Sternes' || fam === 'Laridés' || fam === 'Goélands, mouettes, sternes' || fam === 'Labbes';
  },
  coraciiformes: sci => {
    const g = (sci||'').split(' ')[0];
    if(CORACIIFORMES_G.test(g)) return true;
    const fam = (typeof familyOf === 'function') ? familyOf(sci) : null;
    return fam === 'Guêpiers' || fam === 'Rolliers' || fam === 'Brachyptérolles' || fam === 'Motmots' || fam === 'Todiers';
  },
  suliformes: sci => {
    const g = (sci||'').split(' ')[0];
    if(SULIFORMES_G.test(g)) return true;
    const fam = (typeof familyOf === 'function') ? familyOf(sci) : null;
    return fam === 'Cormorans' || fam === 'Fous' || fam === 'Anhingas' || fam === 'Frégates';
  },
  sturnoidea: sci => {
    const g = (sci||'').split(' ')[0];
    if(STURNOIDEA_G.test(g)) return true;
    const fam = (typeof familyOf === 'function') ? familyOf(sci) : null;
    return fam === 'Étourneaux' || fam === 'Moqueurs' || fam === 'Piqueboeufs' || fam === 'Rhabdornis';
  },
  passeridae: sci => {
    const g = (sci||'').split(' ')[0];
    if(MOINEAUX_ACCENTEURS_G.test(g)) return true;
    const fam = (typeof familyOf === 'function') ? familyOf(sci) : null;
    return fam === 'Moineaux' || fam === 'Accenteurs';
  },
  podicipedidae: sci => {
    const g = (sci||'').split(' ')[0];
    if(PODICIPEDIDAE_G.test(g)) return true;
    const fam = (typeof familyOf === 'function') ? familyOf(sci) : null;
    return fam === 'Grèbes';
  },
  procellariiformes: sci => {
    const g = (sci||'').split(' ')[0];
    if(PROCELLARIIFORMES_G.test(g)) return true;
    const fam = (typeof familyOf === 'function') ? familyOf(sci) : null;
    return fam === 'Albatros' || fam === 'Puffins, pétrels' || fam === 'Océanites';
  },
  cuculidae: sci => {
    const g = (sci||'').split(' ')[0];
    if(CUCULIDAE_G.test(g)) return true;
    const fam = (typeof familyOf === 'function') ? familyOf(sci) : null;
    return fam === 'Coucous';
  },
  // Filtres pour les badges exotiques (utilises par le modal Monde/France).
  hummingbirds: sci => {
    const fam = (typeof familyOf === 'function') ? familyOf(sci) : null;
    return fam === 'Colibris';
  },
  ratites: sci => {
    const fam = (typeof familyOf === 'function') ? familyOf(sci) : null;
    return fam === 'Autruches' || fam === 'Nandous' || fam === 'Casoars et Emeus';
  },
  exoticParrots: sci => {
    if(sci === 'psittacula krameri') return false;
    const fam = (typeof familyOf === 'function') ? familyOf(sci) : null;
    return fam === 'Perroquets' || fam === 'Cacatoès' || fam === 'Perruches' || fam === 'Perroquets de Nouvelle-Zélande';
  },
  toucans: sci => {
    const fam = (typeof familyOf === 'function') ? familyOf(sci) : null;
    return fam === 'Toucans';
  },
  hornbills: sci => {
    const fam = (typeof familyOf === 'function') ? familyOf(sci) : null;
    return fam === 'Calaos';
  },
  shrikes: sci => {
    const fam = (typeof familyOf === 'function') ? familyOf(sci) : null;
    return fam === 'Pies-grièches';
  },
  pelagics: sci => {
    const fam = (typeof familyOf === 'function') ? familyOf(sci) : null;
    return fam === 'Albatros' || fam === 'Puffins, pétrels' || fam === 'Océanites';
  },
  picNoir: sci => sci === 'dryocopus martius',
  penguins: sci => {
    const fam = (typeof familyOf === 'function') ? familyOf(sci) : null;
    return fam === 'Pingouins, guillemots' || fam === 'Manchots';
  },
  waxwings: sci => {
    const fam = (typeof familyOf === 'function') ? familyOf(sci) : null;
    return fam === 'Jaseurs';
  },
  nightjars: sci => {
    const fam = (typeof familyOf === 'function') ? familyOf(sci) : null;
    return fam === 'Engoulevents' || fam === 'Ibijaux' || fam === 'Guacharo' || (fam && fam.startsWith('Podarges'));
  },
  certhioidea: sci => {
    const g = (sci||'').split(' ')[0];
    if(CERTHIOIDEA_G.test(g)) return true;
    const fam = (typeof familyOf === 'function') ? familyOf(sci) : null;
    return fam === 'Sittelles' || fam === 'Tichodrome' || fam === 'Grimpereaux' || fam === 'Troglodytes' || fam === 'Gobemoucherons' || (fam && fam.startsWith('Grimpereaux'));
  },
  motacillidae: sci => {
    const g = (sci||'').split(' ')[0];
    if(MOTACILLIDAE_G.test(g) || ALAUDA_G.test(g)) return true;
    const fam = (typeof familyOf === 'function') ? familyOf(sci) : null;
    return fam === 'Bergeronnettes, pipits' || fam === 'Alouettes' || fam === 'Panure';
  },
  ciconiidae: sci => {
    const g = (sci||'').split(' ')[0];
    if(ECHASSIERS_G.test(g)) return true;
    const fam = (typeof familyOf === 'function') ? familyOf(sci) : null;
    return fam === 'Cigognes' || fam === 'Grues';
  },
};
