// Granularite du selecteur de la fiche espece pour un pays donne.
// Zones que la fiche sait mesurer. Sans bar chart regional, elle ne le sait pas : elle
// afficherait toutes les zones du pays en "absente", quelle que soit l espece, parce que
// buildRegPanel lit monthlyByRegion() et rien d autre. Le Montenegro est dans ce cas - eBird
// ne publie pas de bar chart par opstina, ses trois regions sont des decoupages MONSTAT que
// nous avons definis nous-memes. Il vaut mieux ne pas proposer de selecteur du tout.
// Pays dont eBird ne publie aucune subdivision exploitable : Malte - dont les 68 conseils
// locaux portent zero espece - le Kosovo et les Feroe, dont la colonne de sous-region est
// vide dans la table des hotspots. Ils recoivent une carte d'une seule piece, le pays
// entier, dont le code de zone est le code du pays lui-meme.
const _SANS_DECOUPAGE = new Set(['MT', 'XK', 'FO']);
function _paysSansDecoupage(cc){ return _SANS_DECOUPAGE.has(cc); }
function zonesFichePourPays(cc){
  if(COUNTRIES_REG[cc] && COUNTRIES_REG[cc].zonesMesurables === false) return [];
  if(cc === 'FR') return FR_DEPARTEMENTS;
  return (typeof REGIONS_BY_COUNTRY === 'object' && REGIONS_BY_COUNTRY[cc]) || [];
}
// Nom francais d une zone. Les contours SVG portent leur propre nom, celui que Natural
// Earth donne - en anglais pour la Russie et la Finlande, translittere du bielorusse, ou
// a la forme adjectivale pour la Croatie. Les infobulles des cartes s en servaient, si
// bien qu une zone pouvait s appeler « Vitebsk » dans le selecteur et « Vicebskaja
// voblasc' » sur la carte. La liste des zones fait foi ; le nom du contour ne sert plus
// que de secours.
const _nomsZonesCache = {};
function nomZone(cc, code, secours){
  let t = _nomsZonesCache[cc];
  if(!t){
    t = _nomsZonesCache[cc] = {};
    for(const r of zonesFichePourPays(cc)) if(r && r.code) t[r.code] = r.name;
  }
  return t[code] || secours || code;
}
