const REGION_TO_DEPTS = {};
for(const code in DEPT_NAMES){ const reg = code.slice(0, code.lastIndexOf('-')); (REGION_TO_DEPTS[reg]||(REGION_TO_DEPTS[reg]=[])).push(code); }
for(const reg in REGION_TO_DEPTS) REGION_TO_DEPTS[reg].sort((a,b)=>DEPT_NAMES[a].localeCompare(DEPT_NAMES[b],'fr'));
// Nom lisible d'une région à partir de son code ISO (utilisé dans les compteurs de la carte).
const REGION_NAMES = Object.fromEntries(FR_REGIONS.map(r=>[r.code, r.name]));
// Label zone pour compteurs : jamais affiché - la région/dept sélectionnée est déjà
// visible dans les sélecteurs juste au-dessus, pas besoin de la répéter.
function _zoneLabel(){
  // Renvoie " · <dept>" ou " · <region>" ou " · <pays>", precede d'un separateur.
  // Vide si pays FR sans region/dept (vue nationale par defaut).
  const cty = ebFilter.country || 'FR';
  if(ebFilter.dept){
    const nm = DEPT_NAMES[ebFilter.dept] || ebFilter.dept;
    return ` · ${nm}`;
  }
  if(ebFilter.region && ebFilter.region !== cty){
    const nm = REGION_NAMES[ebFilter.region] || ebFilter.region;
    return ` · ${nm}`;
  }
  if(cty !== 'FR'){
    const map = { ME:'Monténégro', ES:'Espagne', PT:'Portugal', IT:'Italie', GR:'Grèce', HR:'Croatie', AL:'Albanie', MA:'Maroc', CH:'Suisse', BE:'Belgique', DE:'Allemagne', GB:'Royaume-Uni', TR:'Turquie', IS:'Islande' };
    return ` · ${map[cty] || cty}`;
  }
  return '';
}
// (Re)peuple le sélecteur département en fonction de la région choisie.
function _refreshDeptSel(){
  const sel = $('#mapEbDept'), lbl = $('#mapEbDeptLbl'); if(!sel) return;
  const list = REGION_TO_DEPTS[ebFilter.region];
  // Département dispo en mode "hotspots" ET "À cocher" (missing). Cache en "mine" ou sans région.
  const showDept = (mapMode==='hotspots' || mapMode==='missing') && list;
  if(!showDept){
    sel.style.display='none'; if(lbl) lbl.style.display='none';
    return;
  }
  sel.innerHTML = '<option value="">Tous les départements</option>' +
    list.map(c=>`<option value="${esc(c)}">${esc(DEPT_NAMES[c])} (${esc(c.slice(-2))})</option>`).join('');
  sel.value = (ebFilter.dept && list.includes(ebFilter.dept)) ? ebFilter.dept : '';
  if(!list.includes(ebFilter.dept)) ebFilter.dept = '';
  sel.style.display=''; if(lbl) lbl.style.display='';
}
let hotspotSort = 'todo';   // 'todo' (à cocher) | 'recent' (activité 30j)
