$('#copyLinkBtn').addEventListener('click',async()=>{
  try{ await navigator.clipboard.writeText(shareUrl()); const b=$('#copyLinkBtn');
    const t=b.textContent; b.textContent='✓ Copié'; setTimeout(()=>b.textContent=t,1400);
  }catch(e){ /* clipboard blocked */ }
});
$('#inviteBtn')?.addEventListener('click', doInvite);

const fileInput=$('#file'), drop=$('#drop');
// Liste analysee qui attend un prenom pour partir. Voir handleFiles() : plutot que d'ouvrir
// une fenetre du navigateur, on renvoie au champ visible et on garde le travail deja fait.
let _depotEnAttente = null;
async function handleFiles(fileList){
  const f=[...fileList].find(x=>/\.csv$/i.test(x.name)||x.type==='text/csv') || fileList[0];
  if(!f) return;
  if(!myUid){ $('#myStatus').textContent='Connexion en cours, réessayez dans un instant…'; return; }
  // Lire puis analyser un export eBird prend plusieurs secondes sur une grosse liste, et
  // l'ecran ne bougeait pas d'un pixel pendant ce temps : rien ne disait que le fichier
  // avait ete pris. #myStatus porte role="status", donc cette ligne s'ecrit ET s'annonce.
  $('#myStatus').textContent = 'Analyse de ' + f.name + '…';
  let text; try{ text=await f.text(); }catch(e){ $('#myStatus').textContent='Lecture du fichier impossible.'; return; }
  const parsed=ingest(f.name, text);
  if(!parsed){ $('#myStatus').textContent='Fichier non reconnu (est-ce bien un export eBird ?)'; return; }
  // Le prenom se DEMANDE plutot que de se remplacer par un avertissement. Le repli sur le
  // nom du fichier reste, c est lui qui sert le plus souvent ; mais quand il ne donne rien
  // non plus, « ⚠️ Sans nom » partait dans la base et s affichait au classement de tout le
  // groupe, a charge pour la personne de deviner ou le corriger.
  // Signale par Mathis le 2026-09-28 en rejoignant avec un compte neuf : l ecran etant
  // desormais remis a zero au changement de compte, le champ n est plus pre-rempli par la
  // session precedente, et un depot sans prenom est devenu facile.
  // NOM_ABSENT reste le dernier filet, pour les lignes deja enregistrees ainsi.
  let name = ($('#myName').value.trim()) || cleanName(parsed.defaultName, state.people.length+1);
  if(name === NOM_ABSENT){
    // Le champ « Ton prénom » est visible juste au-dessus : on y renvoie, au lieu d'ouvrir
    // par-dessus une fenetre du navigateur qu'on ne peut ni styler, ni annoncer, ni fermer
    // sans perdre le fichier. La liste deja analysee est mise de cote et le depot repart
    // tout seul des qu'un prenom est saisi - sans ca il faudrait redeposer le fichier.
    _depotEnAttente = parsed;
    $('#myStatus').textContent = 'Encore ton prénom : écris-le juste au-dessus, puis appuie sur Entrée.';
    const inp = $('#myName');
    inp.classList.add('attend-saisie');
    // Le champ vit dans « Ma liste ». Si on est ailleurs, l'onglet est en display:none : ni
    // le message ni le champ ne se voient, et focus() ne prend pas sur un element non affiche.
    // On y ramene avant de demander quoi que ce soit.
    if(getComputedStyle($('#viewLoad')).display === 'none'){
      document.querySelector('.tab[data-view="load"]')?.click();
    }
    inp.focus();
    inp.scrollIntoView({ block: 'center', behavior: 'smooth' });
    return;
  }
  await _enregistreListe(parsed, name);
}

// La moitie du depot qui suit le prenom. Fonction a part parce qu'on y revient par deux
// chemins : le depot direct, et la reprise apres qu'un prenom a enfin ete saisi.
async function _enregistreListe(parsed, name){
  $('#myName').value = name;
  $('#myName').classList.remove('attend-saisie');
  // Préserver les coords GPS déjà connues : si l'espèce était déjà là avec lat/lon
  // et que le nouveau CSV ne fournit pas de coords (ex. life list simple),
  // on garde les anciennes. La liste des espèces reste dictée par le CSV.
  const prev = realPeople.find(p=>p.id===myUid)?.species;
  const importAt = Date.now();   // horodatage de cet import (utilisé pour les NOUVELLES espèces)
  if(prev){
    let kept=0, manualKept=0;
    // Pour chaque espèce du CSV : si le CSV n'a pas de coords mais l'ancien oui, on garde.
    // (En revanche si le CSV apporte des coords, il gagne : c'est la meilleure source.)
    // On préserve aussi addedAt : si l'espèce est déjà connue chez ce joueur (manuel OU
    // import précédent), elle n'est PAS considérée comme une nouveauté du fil.
    for(const [k,v] of parsed.species){
      if(!prev.has(k)) continue;
      const old=prev.get(k);
      if((v.lat==null||v.lon==null) && typeof old.lat==='number' && typeof old.lon==='number'){ v.lat=old.lat; v.lon=old.lon; kept++; }
      if(!v.locId && old.locId){ v.locId=old.locId; }
      v.addedAt = old.addedAt || importAt;   // conserve la date d'apparition originelle
    }
    // Nouvelles espèces (dans le CSV mais pas dans prev) : elles apparaissent MAINTENANT.
    for(const [k,v] of parsed.species){
      if(!prev.has(k) && !v.addedAt) v.addedAt = importAt;
    }
    // Préserve les ajouts MANUELS qui ne sont PAS dans le nouveau CSV
    // (l'utilisateur les a saisis à la main, ils ne doivent pas disparaître à chaque ré-import).
    for(const [k,old] of prev){
      if(parsed.species.has(k)) continue;   // le CSV a une version -> elle gagne
      if(old.manual){ parsed.species.set(k, old); manualKept++; }
    }
    if(kept) console.log('Ré-import : '+kept+' coords GPS préservées.');
    if(manualKept) console.log('Ré-import : '+manualKept+' ajouts manuels préservés.');
  } else {
    // Tout premier import : toutes les espèces sont "nouvelles" à cet instant.
    for(const [k,v] of parsed.species) if(!v.addedAt) v.addedAt = importAt;
  }
  $('#myStatus').textContent = '… enregistrement';
  try{
    await saveMyList(name, parsed.species, parsed.regions);
    // Premier depot : les abonnements ont ete refuses au demarrage faute d'etre membre, et
    // Firestore ne rejoue pas un ecouteur refuse. Sans ce rappel la page restait bloquee sur
    // « … enregistrement », la liste enregistree mais invisible (2026-09-28). Un membre qui
    // re-importe n'en a pas besoin : ses abonnements vivent deja.
    if(!iAmInLeague) subscribe();
    // Le retour de Firestore vide #myStatus et repeint la page : la reussite ne laisse donc
    // aucune trace lisible. On l'annonce a part, avec le chiffre qui compte.
    annonce('Liste enregistrée : ' + parsed.species.size + ' espèces.');
  }
  catch(e){ showError(e); $('#myStatus').textContent=''; }
}
// Pas de gestionnaire de clic ici : #drop est une <label for="file">, le navigateur ouvre le
// selecteur tout seul. Le rajouter ouvrirait DEUX fois la fenetre de choix de fichier.
fileInput.addEventListener('change',e=>{ handleFiles(e.target.files); fileInput.value=''; });
['dragenter','dragover'].forEach(ev=>drop.addEventListener(ev,e=>{e.preventDefault();drop.classList.add('drag');}));
['dragleave','drop'].forEach(ev=>drop.addEventListener(ev,e=>{e.preventDefault();drop.classList.remove('drag');}));
drop.addEventListener('drop',e=>{ if(e.dataTransfer?.files) handleFiles(e.dataTransfer.files); });
window.addEventListener('dragover',e=>e.preventDefault());
window.addEventListener('drop',e=>e.preventDefault());

// Fenêtre de grâce après inscription pendant laquelle le renommage est autorisé
// (permet de corriger un nom mal saisi au 1er upload avant que le verrou anti-usurpation ne tombe).
const NAME_GRACE_MS = 24 * 60 * 60 * 1000;
function _nameIsUnlocked(me){
  if(isAdmin()) return true;
  if(!me || !me.joinedAt) return true;                 // pas encore inscrit → toujours modifiable
  return (Date.now() - me.joinedAt*1000) < NAME_GRACE_MS;
}
// Reprise du depot laisse en attente faute de prenom. Sur 'change' (Entree ou sortie du
// champ) plutot que sur chaque frappe : reprendre a la premiere lettre enverrait « M ».
$('#myName').addEventListener('change', async e => {
  if(!_depotEnAttente) return;
  const nm = e.target.value.trim().slice(0, 24);
  if(!nm){ $('#myStatus').textContent = 'Il faut un prénom pour rejoindre la ligue.'; return; }
  const parsed = _depotEnAttente;
  _depotEnAttente = null;
  await _enregistreListe(parsed, nm);
});
$('#myName').addEventListener('change',async e=>{
  const nm=(e.target.value.trim())||'Joueur';
  e.target.value=nm;
  if(!iAmInLeague) return;
  const me = realPeople.find(p=>p.id===myUid);
  const oldName = me?.name || '';
  // Verrou : après la fenêtre de grâce (24h post-inscription), nom non modifiable (sauf admin).
  if(oldName && oldName!==nm && !_nameIsUnlocked(me)){
    e.target.value = oldName;
    alert('Votre nom est verrouillé (24 h après votre inscription). Contactez l\'admin pour un changement.');
    return;
  }
  if(oldName===nm) return;
  try{
    await updateDoc(doc(db,'leagues',leagueId,'members',myUid),{name:nm});
    // D : log du changement pour audit
    if(oldName) await addDoc(collection(db,'leagues',leagueId,'nameChanges'), {
      uid:myUid, oldName, newName:nm, byUid:myUid, byName:nm, ts:serverTimestamp()
    });
  }catch(err){ showError(err); }
});
// Verrou visuel du champ nom : ouvert pendant la fenêtre de grâce (24h post-inscription),
// puis verrouillé (sauf admin). Même règle que le handler 'change' via _nameIsUnlocked.
function _lockMyNameIfSet(){
  const inp = $('#myName'); if(!inp) return;
  const me = realPeople.find(p=>p.id===myUid);
  const hasName = !!(me && me.name);
  if(hasName && !_nameIsUnlocked(me)){
    inp.readOnly = true; inp.classList.add('locked'); inp.title = 'Verrouillé après 24 h : demande à un admin';
  } else {
    inp.readOnly = false; inp.classList.remove('locked');
    inp.title = hasName ? 'Modifiable pendant 24 h après inscription' : '';
  }
}
// H : désactive visuellement écriture chat + upload photo pour les non-membres.
function _refreshChatWriteAccess(){
  const canWrite = iAmInLeague;
  const chatText=$('#chatText'), chatName=$('#chatName'), photoInput=$('#photoInput'), photoPub=$('#photoPublish'), photoLbl=$('#photoAddLabel');
  const hint = 'Chargez votre life list eBird pour écrire';
  if(chatText){ chatText.disabled = !canWrite; chatText.placeholder = canWrite ? 'Votre message…' : hint; }
  if(chatName){ chatName.disabled = !canWrite; }
  if(photoInput){ photoInput.disabled = !canWrite; }
  if(photoPub){ photoPub.disabled = !canWrite; }
  if(photoLbl){ photoLbl.style.opacity = canWrite ? '' : '0.5'; photoLbl.style.pointerEvents = canWrite ? '' : 'none'; photoLbl.title = canWrite ? '' : hint; }
}

