$('#manualAddBtn')?.addEventListener('click', async ()=>{
  const msg=$('#manualMsg'); msg.textContent=''; msg.className='manual-msg';
  if(!manualPickedSci){ msg.className='manual-msg err'; msg.textContent='Choisissez une espèce dans la liste.'; return; }
  if(!myUid){ msg.className='manual-msg err'; msg.textContent='Connexion en cours, réessayez.'; return; }
  const me = realPeople.find(p=>p.id===myUid);
  if(!me){ msg.className='manual-msg err'; msg.textContent='Chargez d\'abord votre liste principale.'; return; }
  const key = manualPickedSci; // sci déjà en lowercase
  if(me.species.has(key)){ msg.className='manual-msg err'; msg.textContent='Cette espèce est déjà dans votre liste.'; return; }
  // pays
  const co = $('#manualCountry').value;
  let country = 'FR';
  if(co==='OTHER'){ const pick=$('#manualCountryPick').value; if(!pick){ msg.className='manual-msg err'; msg.textContent='Choisissez un pays.'; return; } country=pick; }
  const date = $('#manualDate').value || '';   // YYYY-MM-DD
  const sciProper = MANUAL_INDEX.find(x=>x.sci===key).sci.split(' ').map((w,i)=>i===0?w[0].toUpperCase()+w.slice(1):w).join(' ');
  // Lieu + coords : viennent du picker cartographique (modal Leaflet)
  const loc = _manualPickedName || 'Ajout manuel';
  const entry = { common: FR_NAMES[key], sci: sciProper, date, loc, obs: 1,
    fr: country==='FR', country, nonSpecies: false, manual: true, addedAt: Date.now() };
  if(_manualPickedLat!=null && _manualPickedLon!=null){ entry.lat=_manualPickedLat; entry.lon=_manualPickedLon; }
  // mise à jour locale immédiate + sauvegarde
  me.species.set(key, entry);
  const btn=$('#manualAddBtn'); btn.disabled=true;
  try{
    await saveMyList(me.name, me.species);
    msg.className='manual-msg ok'; msg.textContent = `✓ Ajouté : ${entry.common}` + (entry.lat!=null?' (📍 sur la carte)':'');
    // Rafraîchit immédiatement classement, matrice, fiche stats et carte
    // (au lieu d'attendre le round-trip Firestore snapshot)
    renderResults();
    renderStats(me);
    if(document.querySelector('.tab.on')?.dataset.view==='map') renderMap();
    // reset formulaire
    manualPickedSci=null; $('#manualSearch').value=''; $('#manualPicked').style.display='none';
    $('#manualDate').value=''; $('#manualCountry').value='FR'; $('#manualCountryPickWrap').style.display='none';
    $('#manualPlaceStatus').textContent=''; _manualPickedLat=_manualPickedLon=null; _manualPickedName='';
    setTimeout(()=>{ if(msg.className.includes('ok')) msg.textContent=''; }, 3500);
  }catch(err){
    // rollback local si l'écriture Firebase échoue
    me.species.delete(key);
    msg.className='manual-msg err'; msg.textContent = 'Erreur : '+(err?.message||err);
  }
  btn.disabled=false;
});

const VIEWS = { load:'#viewLoad', profil:'#viewProfil', ranking:'#viewRanking', map:'#viewMap', trophies:'#viewTrophies', chat:'#viewChat', photos:'#viewPhotos', feed:'#viewFeed', requests:'#viewRequests', quiz:'#viewQuiz', pokedex:'#viewPokedex', about:'#viewAbout' };
// Hamburger menu + FABs Chat/Photos : delegate vers les tabs caches.
document.addEventListener('click', e => {
  const ham = e.target.closest('#hamburgerBtn');
  if(ham){
    const m = document.getElementById('hamburgerMenu');
    if(m){
      if(m.hidden){
        // Position calculee sous le bouton, aligne a droite. position:fixed pour echapper
        // au overflow:auto de .tabs qui clippait le dropdown en-dessous du nav.
        const r = ham.getBoundingClientRect();
        m.style.top = (r.bottom + 4) + 'px';
        m.style.right = (window.innerWidth - r.right) + 'px';
        m.hidden = false;
      } else m.hidden = true;
    }
    e.stopPropagation();
    return;
  }
  const item = e.target.closest('.ham-item[data-view]');
  if(item){
    const btn = [...document.querySelectorAll('.tab[data-view]')].find(b => b.dataset.view === item.dataset.view);
    if(btn) btn.click();
    const m = document.getElementById('hamburgerMenu'); if(m) m.hidden = true;
    return;
  }
  const fabC = e.target.closest('#fabChat');
  if(fabC){ _toggleFabPanel('chat', fabC); return; }
  const fabP = e.target.closest('#fabPhotos');
  if(fabP){ _toggleFabPanel('photos', fabP); return; }
  const fabF = e.target.closest('#fabFeed');
  if(fabF){ _toggleFabPanel('feed', fabF); return; }
  // Click outside : close hamburger.
  const m = document.getElementById('hamburgerMenu');
  if(m && !m.hidden && !e.target.closest('#hamburgerMenu')) m.hidden = true;
  // Click sur backdrop ou hors panneau : ferme le panneau flottant.
  // On NE ferme PAS si le click est dans les popups liees (emoji / gif / country pickers /
  // fiche espece) car ce sont des UI enfants qui s'ouvrent AU-DESSUS du panneau et leur
  // click ne doit pas etre interprete comme "hors panneau".
  const bd = document.getElementById('fabBackdrop');
  const inPopup = e.target.closest('#emojiPop') || e.target.closest('#gifPop') || e.target.closest('.cp-modal-backdrop') || e.target.closest('#imgModal') || e.target.closest('#speciesModal');
  if(bd && !bd.hidden && !inPopup && (e.target === bd || (!e.target.closest('#viewChat.fab-open') && !e.target.closest('#viewPhotos.fab-open') && !e.target.closest('#viewFeed.fab-open') && !e.target.closest('#fabStack')))){
    _closeFabPanel();
  }
});
// Ouvre / ferme un panneau flottant (chat ou photos). Re-clic sur le meme FAB ferme.
function _toggleFabPanel(view, fabBtn){
  const targetId = view === 'chat' ? 'viewChat' : view === 'photos' ? 'viewPhotos' : view === 'feed' ? 'viewFeed' : null;
  if(!targetId) return;
  const target = document.getElementById(targetId);
  if(!target) return;
  // Deja ouvert -> ferme.
  if(target.classList.contains('fab-open')){ _closeFabPanel(); return; }
  // Ferme l'autre si ouvert.
  _closeFabPanel();
  // Marque le tab correspondant "on" pour synchro visuelle (au cas ou tab visible).
  target.classList.add('fab-open');
  const bd = document.getElementById('fabBackdrop'); if(bd) bd.hidden = false;
  document.querySelectorAll('#fabStack button').forEach(b => b.classList.remove('fab-active'));
  if(fabBtn) fabBtn.classList.add('fab-active');
  // Trigger la logique attachée au tab switch pour re-render le contenu (renderChat, renderPhotos)
  // SANS masquer les autres views.
  if(view === 'chat'){
    if(typeof updateChatIdentity === 'function') updateChatIdentity();
    if(typeof renderOnline === 'function') renderOnline();
    const box = document.getElementById('chatMessages'); if(box) box.scrollTop = box.scrollHeight;
    if(typeof markSeen === 'function') markSeen('chat');
  } else if(view === 'photos'){
    if(typeof renderPhotos === 'function') renderPhotos();
    if(typeof markSeen === 'function') markSeen('photos');
  } else if(view === 'feed'){
    if(typeof renderFeed === 'function') renderFeed();
    if(typeof markSeen === 'function') markSeen('feed');
  }
}
function _closeFabPanel(){
  document.querySelectorAll('#viewChat, #viewPhotos, #viewFeed').forEach(el => el.classList.remove('fab-open'));
  document.querySelectorAll('#fabStack button').forEach(b => b.classList.remove('fab-active'));
  const bd = document.getElementById('fabBackdrop'); if(bd) bd.hidden = true;
}
document.querySelectorAll('.tab').forEach(b=>b.addEventListener('click',()=>{
  // Skip les .tab sans data-view (hamburger btn), sinon on masque toutes les views
  // (le loop VIEWS ne match rien et met tout a display:none, ecran blanc).
  if(!b.dataset.view) return;
  document.querySelectorAll('.tab').forEach(x=>x.classList.remove('on'));
  b.classList.add('on');
  Object.entries(VIEWS).forEach(([v,sel])=>{ const el=$(sel); if(el) el.style.display=(b.dataset.view===v)?'':'none'; });
  if(b.dataset.view==='chat'){
    updateChatIdentity();
    renderOnline();
    const box=$('#chatMessages'); if(box) box.scrollTop=box.scrollHeight;
    $('#chatText')?.focus();
    markSeen('chat');
  }
  if(b.dataset.view==='photos'){ renderPhotos(); markSeen('photos'); }
  if(b.dataset.view==='feed'){ renderFeed(); markSeen('feed'); }
  if(b.dataset.view==='profil'){ const me=realPeople.find(p=>p.id===myUid); fillProfile(me); renderStats(me); }
  if(b.dataset.view==='requests'){ renderRequests(); markSeen('requests'); }
  if(b.dataset.view==='quiz') renderQuizInit();
  if(b.dataset.view==='pokedex') renderPokedex();
  if(b.dataset.view==='map') renderMap();
  // Flush les renders differes pour ranking/trophies (voir renderResults + _rankingDirty).
  if(b.dataset.view==='ranking' || b.dataset.view==='trophies') _flushDirtyForView(b.dataset.view);
  try{ localStorage.setItem('mb-last-tab', b.dataset.view); }catch(_){ }
}));
