// ---- Autocomplétion @mention dans le chat ----
let _mnOpen=false, _mnMatches=[], _mnActive=0;
function _mnNorm(s){ return (s||'').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g,'').replace(/[^a-z0-9]/g,''); }
function _mnClose(){ const p=$('#chatMentionPop'); if(p){ p.classList.remove('open'); p.innerHTML=''; } _mnOpen=false; _mnMatches=[]; _mnActive=0; }
function _mnRenderUI(){
  const p=$('#chatMentionPop'); if(!p) return;
  p.innerHTML = _mnMatches.map((m,i)=>{
    const self = m.uid===myUid?'<span class="self">vous</span>':'';
    return `<div class="mention-pop-item ${i===_mnActive?'active':''}" data-idx="${i}" style="--series:var(--s${m.si})">
      <span class="dot"></span>${esc(m.name)}${self}</div>`;
  }).join('');
}
function _mnInsert(m){
  const ti=$('#chatText'); if(!ti) return;
  const val=ti.value, pos=ti.selectionStart||val.length;
  const before=val.slice(0,pos), after=val.slice(pos);
  const nb=before.replace(/@([A-Za-zÀ-ÿ][A-Za-zÀ-ÿ'\-]*)?$/,'@'+m.first+' ');
  ti.value=nb+after; ti.selectionStart=ti.selectionEnd=nb.length; ti.focus(); _mnClose();
}
function _mnUpdate(){
  const ti=$('#chatText'); if(!ti) return;
  const val=ti.value, pos=ti.selectionStart||0, before=val.slice(0,pos);
  const m = before.match(/(?:^|\s)@([A-Za-zÀ-ÿ][A-Za-zÀ-ÿ'\-]*)?$/);
  if(!m){ _mnClose(); return; }
  const q = _mnNorm(m[1]||'');
  const members = realPeople.map(p=>({ uid:p.id, name:p.name, si:p.si,
    first:(p.name||'').split(/\s+/)[0]||p.name,
    normF:_mnNorm((p.name||'').split(/\s+/)[0]||p.name), normA:_mnNorm(p.name) }));
  _mnMatches = members.filter(x=>!q||x.normF.startsWith(q)||x.normA.includes(q)).slice(0,8);
  if(!_mnMatches.length){ _mnClose(); return; }
  _mnActive=0; _mnOpen=true; $('#chatMentionPop').classList.add('open'); _mnRenderUI();
}
$('#chatText')?.addEventListener('input', _mnUpdate);
$('#chatText')?.addEventListener('click', _mnUpdate);
$('#chatText')?.addEventListener('keydown', e=>{
  if(!_mnOpen) return;
  if(e.key==='ArrowDown'){ e.preventDefault(); _mnActive=(_mnActive+1)%_mnMatches.length; _mnRenderUI(); }
  else if(e.key==='ArrowUp'){ e.preventDefault(); _mnActive=(_mnActive-1+_mnMatches.length)%_mnMatches.length; _mnRenderUI(); }
  else if(e.key==='Enter'||e.key==='Tab'){ if(_mnMatches[_mnActive]){ e.preventDefault(); _mnInsert(_mnMatches[_mnActive]); } }
  else if(e.key==='Escape'){ e.preventDefault(); _mnClose(); }
});
$('#chatMentionPop')?.addEventListener('mousedown', e=>{ e.preventDefault(); const it=e.target.closest('.mention-pop-item'); if(it){ const i=+it.dataset.idx; if(_mnMatches[i]) _mnInsert(_mnMatches[i]); } });
$('#chatText')?.addEventListener('blur', ()=>setTimeout(_mnClose, 200));
$('#emojiPop')?.addEventListener('click', async e=>{
  if(e.target.id==='emojiPop'){ closeEmojiPop(); return; }
  const b=e.target.closest('.emoji-opt'); if(!b) return;
  const emoji=b.dataset.emoji;
  if(emojiContext?.type==='text'){ const ti=$('#chatText'); if(ti){ ti.value+=emoji; ti.focus(); } }
  else if(emojiContext?.type==='react'){ await toggleReaction(emojiContext.target, emoji); }
  else if(emojiContext?.type==='avatar'){
    await saveProfile({ avatar: emoji });
    const me = realPeople.find(p => p.id === myUid); if(me){ me.avatar = emoji; _renderAvatarPreview(me); }
  }
  closeEmojiPop();
});
