    // pour le departement qu'on venait de cliquer.
    const _parZone = (typeof REAL_FREQ_MONTHLY_BY_REGION_MULTI === 'object')
      ? REAL_FREQ_MONTHLY_BY_REGION_MULTI[cc] : null;
