  const prev = $('#smNavPrev'), next = $('#smNavNext');
  const canNav = _speciesNavPool.length && _speciesNavIdx >= 0;
  if(prev){ prev.disabled = !canNav || _speciesNavIdx <= 0; prev.style.opacity = prev.disabled ? '.35' : '1'; }
  if(next){ next.disabled = !canNav || _speciesNavIdx >= _speciesNavPool.length - 1; next.style.opacity = next.disabled ? '.35' : '1'; }
  const key = sci.toLowerCase();
  const modal = $('#speciesModal'); if(!modal) return;
  const nm = FR_NAMES[key] || sci;
  $('#smTitle').textContent = nm;
  $('#smSci').textContent = sci;
  // Header : degrade base sur la couleur du 1er habitat de l'espece. Un couleur par milieu
  // (foret=vert, eau=bleu, montagne=violet, urbain=gris, etc.).
  const hdr = modal.querySelector('.sm-header');
  if(hdr){
    const habs = habitatsOf(sci) || [];
    // Palette adaptee aux 12 categories Avonet (migration 2026-08).
    // Chaque couleur choisie pour rester lisible en fond header (contraste texte auto via
    // luminance sur .sm-header-dark-text).
    const HAB_COLORS = {
      forest:    '#2d7a3f',   // vert forêt
      woodland:  '#5ba85f',   // vert bois clair
      shrubland: '#8a9a3f',   // olive/kaki
      grassland: '#c99a3f',   // ocre/prairie
      wetland:   '#1e6f6a',   // bleu-vert (roselières)
      riverine:  '#1e6091',   // bleu eau douce
      marine:    '#1a3d75',   // bleu marine
      coastal:   '#3a92c4',   // bleu clair côte
      rock:      '#8b6b47',   // brun rocher
      desert:    '#d19a5b',   // sable
      humanmod:  '#6b6f75',   // gris urbain
      aerial:    '#6ab4d8',   // bleu ciel
    };
    const c = (habs.length && HAB_COLORS[habs[0]]) || sciColor(sci);
    hdr.style.background = `linear-gradient(135deg, ${c} 0%, color-mix(in srgb, ${c} 55%, #000) 100%)`;
    // Contraste texte auto : hex -> luminance perceptuelle. Fond clair -> texte fonce.
    const hex2rgb = h => { const m = /^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(h); return m ? [parseInt(m[1],16), parseInt(m[2],16), parseInt(m[3],16)] : [128,128,128]; };
    const [rr,gg,bb] = hex2rgb(c);
    const lum = (0.299*rr + 0.587*gg + 0.114*bb) / 255;
    hdr.classList.toggle('sm-header-dark-text', lum > 0.62);
  }
  // Restaure le dernier onglet visite (defaut : Info).
  let lastTab = 'info';
