/* ---------------- go ---------------- */
showLeague();   // affiche la page tout de suite, sans attendre la connexion
/* ---------------- connexion email ---------------- */
function isRealAccount(u){ return !!u && !u.isAnonymous; }
function authErr(e){
  const c=(e&&e.code)||'';
  if(c==='auth/invalid-email') return 'Email invalide.';
  if(c==='auth/weak-password') return 'Mot de passe trop court (6 caractères minimum).';
  if(c==='auth/email-already-in-use') return 'Cet email a déjà un compte - clique sur « J\'ai déjà un compte ».';
  if(c==='auth/credential-already-in-use') return 'Ce compte existe déjà - connecte-toi avec « J\'ai déjà un compte ».';
  if(c==='auth/invalid-credential'||c==='auth/wrong-password'||c==='auth/user-not-found') return 'Email ou mot de passe incorrect.';
  if(c==='auth/missing-password') return 'Entre ton mot de passe.';
  if(c==='auth/too-many-requests') return 'Trop de tentatives, réessaie dans un moment.';
  if(c==='auth/operation-not-allowed') return 'La connexion par email n\'est pas encore activée côté Firebase.';
  return (e&&e.message)||'Erreur.';
}
function authMsg(txt, ok){ const el=$('#authMsg'); if(!el) return; el.textContent=txt||''; el.className='auth-msg'+(txt?(ok?' ok':' err'):''); }
function updateAuthUI(user){
  const box=$('#authBox');
  const real=isRealAccount(user);
  // Personne de connecte : il n y a aucune donnee a attendre, le portail peut venir.
  if(!real) _retireSplash();
  // Gate d'auth : bloque tout l'acces a l'app tant que pas connecte avec un vrai compte.
  // Etat via [data-auth] sur <html> : 'signed-in' | 'signed-out' | 'pending'.
  document.documentElement.setAttribute('data-auth', real ? 'signed-in' : 'signed-out');
  // Compat classes (a retirer eventuellement)
  document.body.classList.toggle('auth-gated', !real);
  document.documentElement.classList.toggle('auth-gated', !real);
  const gate = $('#authGate');
  if(gate){
    gate.hidden = !!real;
    // Reset consent UI selon le tab courant
    _authGateSyncTab();
  }
  // Load page : masque l'ancien authBox (deprecated, remplace par le gate)
  if(box) box.style.display = 'none';
  const authForm = $('#authForm'); if(authForm) authForm.style.display = 'none';
  const authInfo = $('#authInfo'); if(authInfo) authInfo.style.display = 'none';
  // Sync hamburger : email + boutons signin/signout selon etat
  const info = $('#hamAccountInfo');
  const emailEl = $('#hamAccountEmail');
  const signin = $('#hamSignin');
  const signout = $('#hamSignout');
  if(real){
    if(info) info.hidden = false;
    if(emailEl) emailEl.textContent = user.email || '';
    if(signin) signin.hidden = true;
    if(signout) signout.hidden = false;
  } else {
    if(info) info.hidden = true;
    if(emailEl) emailEl.textContent = '';
    if(signin) signin.hidden = false;
    if(signout) signout.hidden = true;
  }
}
// ============ AUTH GATE handlers ============
let _authGateMode = 'signin';   // 'signin' | 'signup'
/*
  Verifie un code SANS etre connecte : la regle ouvre `get` sur /invites a qui connait
  deja le code. C'est ce qui permet de refuser l'inscription avant de creer le compte,
  donc sans laisser de comptes fantomes dans Firebase.
  Un code deja pris par QUELQU'UN D'AUTRE est refuse ; repris par la meme personne, il
  passe, pour qu'un echec en cours de route ne la laisse pas dehors.
*/
async function _verifieCodeInvitation(saisi){
  const code = String(saisi || '').trim().toUpperCase();
  if(!code) return { ok:false, message:'Il faut un code d\'invitation pour créer un compte. Demande-le à la personne qui t\'a parlé de la ligue.' };
  let snap;
  try{ snap = await getDoc(doc(db, 'leagues', leagueId, 'invites', code)); }
  catch(_){ return { ok:false, message:'Impossible de vérifier le code pour le moment. Réessaie dans un instant.' }; }
  if(!snap.exists()) return { ok:false, message:'Ce code n\'existe pas. Vérifie que tu l\'as recopié en entier.' };
  const d = snap.data() || {};
  const moi = auth.currentUser && auth.currentUser.uid;
  if(d.usedBy && d.usedBy !== moi) return { ok:false, message:'Ce code a déjà servi. Demande-en un autre.' };
  return { ok:true, code };
}
// Arrivee par un lien d'invitation : le code est dans l'URL, on epargne un copier-coller.
try{
  const _c = new URLSearchParams(location.search).get('code');
  if(_c){
    const _i = $('#authGateInvite'); if(_i) _i.value = _c.trim().toUpperCase();
    _authGateMode = 'signup';
  }
}catch(_){ }
function _authGateSyncTab(){
  // aria-selected suit la classe .on, et le formulaire dit de quel onglet il depend : sans
  // ca, rien n'annonce si on est en train de se connecter ou de creer un compte.
  document.querySelectorAll('.auth-gate-tab').forEach(b => {
    const actif = b.dataset.authTab === _authGateMode;
    b.classList.toggle('on', actif);
    b.setAttribute('aria-selected', actif ? 'true' : 'false');
  });
  const form = $('#authGateForm');
  if(form) form.setAttribute('aria-labelledby', _authGateMode === 'signin' ? 'authGateTabSignin' : 'authGateTabSignup');
  const cta = $('#authGateSubmit');
  if(cta) cta.textContent = _authGateMode === 'signin' ? 'Se connecter' : 'Créer mon compte';
  const consent = $('#authGateConsentWrap');
  if(consent) consent.hidden = _authGateMode !== 'signup';
  const invit = $('#authGateInviteWrap');
  if(invit) invit.hidden = _authGateMode !== 'signup';
  const passInput = $('#authGatePass');
  if(passInput) passInput.setAttribute('autocomplete', _authGateMode === 'signin' ? 'current-password' : 'new-password');
  const forgot = $('#authGateForgot');
  if(forgot) forgot.hidden = _authGateMode !== 'signin';
  const msg = $('#authGateMsg'); if(msg){ msg.textContent = ''; msg.className = 'auth-gate-msg'; }
}
function _authGateMsg(txt, ok){
  const el = $('#authGateMsg'); if(!el) return;
  el.textContent = txt || '';
  el.className = 'auth-gate-msg' + (txt ? (ok ? ' ok' : ' err') : '');
}
document.addEventListener('click', async e => {
  const tab = e.target.closest('.auth-gate-tab');
  if(tab){ _authGateMode = tab.dataset.authTab; _authGateSyncTab(); return; }
  const sw = e.target.closest('.auth-gate-switch');
  if(sw){ e.preventDefault(); _authGateMode = sw.dataset.switchTo; _authGateSyncTab(); return; }
  const submit = e.target.closest('#authGateSubmit');
  if(submit){
    const email = $('#authGateEmail')?.value.trim();
    const pass = $('#authGatePass')?.value;
    if(!email || !pass){ _authGateMsg('Entre un email et un mot de passe.'); return; }
    if(_authGateMode === 'signup'){
      const consent = $('#authGateConsent')?.checked;
      if(!consent){ _authGateMsg('Accepte les conditions de confidentialité pour continuer.'); return; }
      const inv = await _verifieCodeInvitation($('#authGateInvite')?.value);
      if(!inv.ok){ _authGateMsg(inv.message); $('#authGateInvite')?.focus(); return; }
      submit.disabled = true; _authGateMsg('…', true);
      try{
        const cur = auth.currentUser;
        if(cur && cur.isAnonymous){ await linkWithCredential(cur, EmailAuthProvider.credential(email, pass)); _authGateMsg('Compte créé - ta liste est conservée ✓', true); }
        else { await createUserWithEmailAndPassword(auth, email, pass); _authGateMsg('Compte créé ✓', true); }
        // Le code est marque pris tout de suite, et garde en local : c'est au depot de
        // la liste que la regle d'entree le relira (etape 3). Si cette ecriture echoue,
        // le depot la retentera - reprendre son propre code est permis.
        try{ localStorage.setItem('mb-invite', inv.code); }catch(_){ }
        try{ await updateDoc(doc(db, 'leagues', leagueId, 'invites', inv.code),
          { usedBy: auth.currentUser.uid, usedAt: serverTimestamp() }); }catch(_){ }
        $('#authGatePass').value = ''; updateAuthUI(auth.currentUser);
      }catch(err){ _authGateMsg(authErr(err)); }
      submit.disabled = false;
    } else {
      submit.disabled = true; _authGateMsg('…', true);
      try{
        await signInWithEmailAndPassword(auth, email, pass);
        $('#authGatePass').value = ''; _authGateMsg('Connecté ✓', true);
        updateAuthUI(auth.currentUser);
      }catch(err){ _authGateMsg(authErr(err)); }
      submit.disabled = false;
    }
    return;
  }
  const forgot = e.target.closest('#authGateForgot');
  if(forgot){
    const email = $('#authGateEmail')?.value.trim();
    if(!email){ _authGateMsg('Entre ton email d\'abord.'); $('#authGateEmail')?.focus(); return; }
    try{ await sendPasswordResetEmail(auth, email); _authGateMsg('Email envoyé à ' + email + ' · Pense à vérifier tes spams', true); }
    catch(err){ _authGateMsg(authErr(err)); }
    return;
  }
});
